  'The payment provider could not verify your identity, so the purchase was stopped.': 'Mtoa huduma wa malipo hakuweza kuthibitisha utambulisho wako, kwa hiyo ununuzi umesimamishwa.',
  'The payment provider had a problem. You were not charged — try again in a moment.': 'Mtoa huduma wa malipo amepata tatizo. Hujatozwa — jaribu tena baada ya muda mfupi.',
  'The payment window could not load. Check that pop-up or tracker blockers allow onramp.arc.io, then try again.': 'Dirisha la malipo halikuweza kufunguka. Hakikisha vizuizi vya madirisha ibukizi au vifuatiliaji vinaruhusu onramp.arc.io, kisha ujaribu tena.',
  'The purchase did not complete. You were not charged.': 'Ununuzi haukukamilika. Hujatozwa.',
