  // landing page
  "{pct}% of the 1,000,000,000 supply": "{pct}% ya ugavi wa 1,000,000,000",
  "0.5% of the transfer (min $0.05, max $50)": "0.5% ya uhamisho (chini $0.05, juu $50)",
  "1% platform fee + the coin’s creator tax (0–3%)": "Ada ya jukwaa 1% + kodi ya muundaji wa sarafu (0–3%)",
  "2% of each trade, in USDC": "2% ya kila biashara, kwa USDC",
  "85% — the other 15% rewards the trader’s referrer": "85% — 15% iliyobaki ni zawadi kwa aliyemwalika mfanyabiashara",
  "90% — Circle keeps 10%": "90% — Circle inabaki na 10%",
  "A trading wallet in your browser: buy and sell in one tap, no pop-ups. Protect it with a passkey.": "Pochi ya biashara kwenye kivinjari chako: nunua na uuze kwa mguso mmoja, bila madirisha ibukizi. Ilinde kwa passkey.",
  "All of ARCDEX’s own fee revenue: its share of swap fees, launchpad fees and bridge fees. Referral rewards and creators’ shares are paid to them first; everything the platform keeps goes to buyback and burn.": "Mapato yote ya ada ya ARCDEX yenyewe: sehemu yake ya ada za swap, za launchpad na za daraja. Zawadi za rufaa na sehemu za waundaji hulipwa kwao kwanza; kila kitu kinachobaki kwa jukwaa huenda kwenye kununua tena na kuchoma.",
  "All platform fees land in the ARCDEX fee wallet — anyone can watch it on-chain.": "Ada zote za jukwaa huingia kwenye pochi ya ada ya ARCDEX — yeyote anaweza kuifuatilia on-chain.",
  "App": "Programu",
  "Arc explorer": "Kivinjari cha bloku cha Arc",
  "ARCDEX is the social trading app for Arc: a terminal for every new coin, one-tap trading, live trader activity, clans, leaderboards and a launchpad. Everything settles on-chain in USDC, and you always keep your own keys.": "ARCDEX ni programu ya biashara ya kijamii ya Arc: terminal kwa kila sarafu mpya, biashara kwa mguso mmoja, shughuli za wafanyabiashara mubashara, vikundi, ubao wa viongozi na launchpad. Kila kitu hukamilika on-chain kwa USDC, na daima unabaki na funguo zako.",
  "Bridge (Circle CCTP)": "Daraja (Circle CCTP)",
  "Built for the coins launching on Arc every day — fast, social and safe.": "Imejengwa kwa sarafu zinazozinduliwa kila siku kwenye Arc — haraka, ya kijamii na salama.",
