  "New coins that pass every hard safety check and show real buying, from every Arc launchpad.": "Sarafu mpya zinazopita kila ukaguzi mkali wa usalama na kuonyesha ununuzi halisi, kutoka kila launchpad ya Arc.",
  "took profit": "faida imechukuliwa",
