  "Fast scalp": "Scalp ya haraka",
  "Coins with a risk flag (the creator holds a big stake, launches coin after coin, or copies a ticker) are traded small and fast: a fifth of the size, most of it sold at +30%, out the moment the creator sells, never held over 15 minutes.": "Sarafu zenye alama ya hatari (muundaji ana hisa kubwa, anazindua sarafu moja baada ya nyingine, au ananakili tika) zinauzwa kidogo na haraka: sehemu ya tano ya ukubwa, nyingi zinauzwa kwa +30%, kutoka mara muundaji anapouza, hazishikiliwi zaidi ya dakika 15.",
