  "Switch to live trading?": "Badilisha kwenda biashara halisi?",
  "From now on the bot buys and sells every signal it can reach with the bot wallet's USDC. Trades can lose money, and most new coins go to zero.": "Kuanzia sasa bot itanunua na kuuza kila ishara inayoweza kufikia kwa USDC ya pochi ya bot. Biashara zinaweza kupoteza pesa, na sarafu nyingi mpya hushuka hadi sifuri.",
  "Cancel": "Ghairi",
