  "Autotrade": "Autotrade",
  "Autotrade scans every new coin on every Arc launchpad, rejects the unsafe ones and trades the rest with the strategies you choose. Start with virtual USDC: paper trading, no money moves.": "Autotrade huchanganua kila sarafu mpya kwenye kila launchpad ya Arc, hukataa zisizo salama na kuuza zilizobaki kwa mikakati unayochagua. Anza na USDC ya mtandaoni: biashara ya majaribio, hakuna pesa inayohamishwa.",
