  "Try Autotrade with virtual USDC": "Jaribu Autotrade kwa USDC ya mtandaoni",
  "Get a paper account, deposit virtual USDC, pick your strategies and press Start. It trades every matching signal around the clock, even with this page closed. No wallet or real money needed.": "Pata akaunti ya majaribio, weka USDC ya mtandaoni, chagua mikakati yako kisha bonyeza Anza. Itauza kila ishara inayolingana saa zote, hata ukurasa huu ukiwa umefungwa. Huhitaji pochi wala pesa halisi.",
