  "Open trades": "Biashara zilizo wazi",
  "Waiting for the next signal. The scanner above shows what it is checking.": "Inasubiri ishara inayofuata. Kichanganuzi hapo juu kinaonyesha kinachokagua.",
  "No open trades.": "Hakuna biashara iliyo wazi.",
  "Closed trades": "Biashara zilizofungwa",
  "Start over with an empty account?": "Anza upya na akaunti tupu?",
  "Yes, reset it": "Ndiyo, iweke upya",
  "Reset my paper account": "Weka upya akaunti yangu ya majaribio",
  "Running · {v} virtual": "Inaendelea · {v} za mtandaoni",
  "Scanning {n} coins · start with virtual USDC": "Inachanganua sarafu {n} · anza na USDC ya mtandaoni",
  "Start with virtual USDC": "Anza na USDC ya mtandaoni",
  "A signal engine scans every new coin on every Arc launchpad, rejects the unsafe ones and trades the rest for you. Start free with virtual USDC.": "Injini ya ishara huchanganua kila sarafu mpya kwenye kila launchpad ya Arc, hukataa zisizo salama na kukuuzia zilizobaki. Anza bure kwa USDC ya mtandaoni.",
  "It scans every coin": "Huchanganua kila sarafu",
  "Every new coin on every Arc launchpad is checked the moment it trades: a real buy-and-sell honeypot test, mint, freeze and pause powers, the creator’s stake, bundled launches, wallet clusters and wash trading.": "Kila sarafu mpya kwenye kila launchpad ya Arc hukaguliwa mara inapouzwa: jaribio halisi la kununua na kuuza (honeypot), uwezo wa kutengeneza, kuzuia na kusimamisha, hisa ya muundaji, uzinduzi uliopangwa, makundi ya pochi na biashara bandia.",
  "You choose the strategies": "Unachagua mikakati",
  "Snipe, Fast scalp, Second leg: use one, or several at once, and set how much goes into each trade.": "Snipe, scalp ya haraka, wimbi la pili: tumia mmoja au kadhaa kwa pamoja, na uamue kiasi kwa kila biashara.",
  "It trades around the clock": "Huuza saa zote",
  "Deposit virtual USDC and press Start. Autotrade takes every matching signal with automatic take-profits and stops, even while you’re away, and shows why it skipped every other coin.": "Weka USDC ya mtandaoni kisha bonyeza Anza. Autotrade huchukua kila ishara inayolingana ikiwa na uchukuaji faida na vizuizi vya kiotomatiki, hata ukiwa mbali, na huonyesha kwa nini iliruka kila sarafu nyingine.",
  "What is Autotrade?": "Autotrade ni nini?",
  "Autotrade is ARCDEX’s signal engine. It scans every new coin on Arc, rejects the unsafe ones with the reason shown, and trades the rest with the strategies you pick. You start with virtual USDC (paper trading), so you can see how it does before risking anything. Results are measured, never promised: most new coins go to zero.": "Autotrade ni injini ya ishara ya ARCDEX. Huchanganua kila sarafu mpya kwenye Arc, hukataa zisizo salama ikionyesha sababu, na kuuza zilizobaki kwa mikakati unayochagua. Unaanza na USDC ya mtandaoni (biashara ya majaribio), ili uone inavyofanya kabla ya kuhatarisha chochote. Matokeo hupimwa, hayaahidiwi: sarafu nyingi mpya hushuka hadi sifuri.",
  "Try Autotrade": "Jaribu Autotrade",
  "Autotrade: a safety scanner that trades for you": "Autotrade: kichanganuzi cha usalama kinachokuuzia",
  "Most new coins are traps. Autotrade checks every one, skips the unsafe ones and trades the rest with your strategies. Try it free with virtual USDC.": "Sarafu nyingi mpya ni mitego. Autotrade hukagua kila moja, huruka zisizo salama na kuuza zilizobaki kwa mikakati yako. Ijaribu bure kwa USDC ya mtandaoni.",
  "coins being scanned right now": "sarafu zinachanganuliwa sasa",
  "checks a minute": "ukaguzi kwa dakika",
  "signals in 24h": "ishara ndani ya saa 24",
  "rejected in 24h": "zimekataliwa ndani ya saa 24",
  "Try Autotrade free": "Jaribu Autotrade bure",
  "Paper trading uses virtual USDC: no money moves. Results are measured, never promised, and most new coins go to zero. Not financial advice.": "Biashara ya majaribio hutumia USDC ya mtandaoni: hakuna pesa inayohamishwa. Matokeo hupimwa, hayaahidiwi, na sarafu nyingi mpya hushuka hadi sifuri. Si ushauri wa kifedha.",
  "Searching all of Arc…": "Inatafuta Arc yote…",
  "More on Arc": "Zaidi kwenye Arc",
  "coins not in this list": "sarafu zisizo kwenye orodha hii",
  "No token at this address on Arc.": "Hakuna tokeni kwenye anwani hii kwenye Arc.",
  "not listed yet": "bado haijaorodheshwa",
  "Create your Autotrade bot": "Unda boti yako ya Autotrade",
  "Name it, pick its strategies and fund it with virtual USDC. It sizes every trade itself to lock in $1–4 (fast scalps $1–2), gets out of rugs at once and learns from its losing trades. It keeps trading with this page closed. No wallet or real money needed.": "Lipe jina, chagua mikakati yake na uiweke USDC ya mtandaoni. Hupanga ukubwa wa kila biashara yenyewe ili kupata $1–4 (scalp za haraka $1–2), hutoka mara moja kwenye rug pull na hujifunza kutoka kwa biashara zake zilizopata hasara. Huendelea kufanya biashara hata ukurasa huu ukifungwa. Hakuna pochi wala pesa halisi inayohitajika.",
  "Bot name": "Jina la boti",
  "e.g. Night Owl": "mf. Night Owl",
