  "Rename": "Badilisha jina",
  "Paused after {n} losses in a row: no new trades until {t} while it learns from them.": "Imesimamishwa baada ya hasara {n} mfululizo: hakuna biashara mpya hadi {t} inapojifunza kutoka kwazo.",
  "Trade size: automatic": "Ukubwa wa biashara: wenyewe",
  "You don't set an amount: each trade is the smallest that locks in its profit target after fees and price impact, and is sold in full there. A pool too thin to pay it is skipped.": "Hauweki kiasi: kila biashara ni ndogo zaidi inayoweza kufikia lengo lake la faida baada ya ada na athari ya bei, na huuzwa yote hapo. Bwawa lenye kina kidogo mno kulipa hilo hurukwa.",
  "What {name} learned": "Alichojifunza {name}",
  "your bot": "boti yako",
  "Nothing yet. After a few closed trades it reads the losing ones and adjusts its filters and take-profit; every change is shown here with the reason, and a change that does worse is rolled back.": "Bado hakuna. Baada ya biashara chache kufungwa, husoma zilizopata hasara na kurekebisha vichujio vyake na kiwango cha kuchukua faida; kila mabadiliko huonyeshwa hapa pamoja na sababu, na mabadiliko yanayofanya vibaya zaidi hurudishwa nyuma.",
  "Protection": "Ulinzi",
  "Rug guard: out at once when liquidity is pulled, an early insider or a whale dumps, the price crashes on heavy selling, or the creator sells.": "Kinga ya rug: hutoka mara moja ukwasi ukiondolewa, mtu wa ndani wa mapema au nyangumi akiuza kwa wingi, bei ikiporomoka kwa mauzo makubwa, au muundaji akiuza.",
  "Pauses new trades for 30 minutes after {n} losses in a row (now {s} in a row).": "Husimamisha biashara mpya kwa dakika 30 baada ya hasara {n} mfululizo (sasa {s} mfululizo).",
  "Daily loss limit {l}: no new trades after it until tomorrow (UTC). Today: {t}.": "Kikomo cha hasara kwa siku {l}: baada yake hakuna biashara mpya hadi kesho (UTC). Leo: {t}.",
  "Stops if the account falls {p}% below what was deposited.": "Husimama akaunti ikishuka {p}% chini ya kilichowekwa.",
