  "Every trade it closes is kept, with the coin's numbers at entry and why it closed: what it learns from.": "Kila biashara inayofungwa huhifadhiwa, pamoja na takwimu za sarafu wakati wa kuingia na sababu ya kufungwa: ndiko inakojifunza.",
  "Download CSV": "Pakua CSV",
  "Load more": "Pakia zaidi",
  "Quick in and out for $1–2: bursts of real buying on any safe coin, and new coins with a risk flag. Sold in full at +15% to start, −10% stop, out within 10 minutes, and at once if the creator sells.": "Kuingia na kutoka haraka kwa $1–2: mlipuko wa ununuzi halisi kwenye sarafu yoyote salama, na sarafu mpya zenye alama ya hatari. Huuzwa yote kwa +15% mwanzoni, stop −10%, hutoka ndani ya dakika 10, na mara moja muundaji akiuza.",
