  "New bot": "Boti mpya",
  "If that email has an account, a new passcode is on its way. Sign in with it, then change it if you like.": "Ikiwa barua pepe hiyo ina akaunti, nambari mpya ya siri iko njiani. Ingia nayo, kisha uibadilishe ukipenda.",
  "Your Autotrade bots, on any device": "Boti zako za Autotrade, kwenye kifaa chochote",
