  "Real money: this bot will trade its wallet's USDC on every signal it takes, with its learned settings, until you switch it back. 2% of each winning trade's profit goes to the platform; losing trades pay nothing. Results aren't guaranteed: most new coins go to zero.": "Pesa halisi: boti hii itafanya biashara kwa USDC ya pochi yake kwenye kila ishara inayochukua, kwa mipangilio iliyojifunza, hadi uirudishe. 2% ya faida ya kila biashara inayoshinda huenda kwa jukwaa; biashara zinazopoteza hazilipi chochote. Matokeo hayajahakikishwa: sarafu nyingi mpya hushuka hadi sifuri.",
