  "Follow traders, join clans.": "Fuata wafanyabiashara, jiunge na makundi.",
  "Your own trading bot on ARCDEX. It scans every new coin on Arc, skips the unsafe ones and trades the rest with the strategies you pick, around the clock.": "Boti yako mwenyewe ya biashara kwenye ARCDEX. Huchanganua kila sarafu mpya kwenye Arc, huacha zisizo salama na hufanya biashara na zilizobaki kwa mikakati unayochagua, saa zote.",
  "How does a bot improve itself?": "Boti hujiboresha vipi?",
  "After trades close, it reads its losing ones and adjusts its take-profit and entry filters. Every change is logged with its reason, and a change that makes it win less is rolled back.": "Biashara zikifungwa, husoma zilizopata hasara na kurekebisha take-profit na vichujio vya kuingia. Kila badiliko hurekodiwa na sababu yake, na badiliko linalomfanya ashinde kidogo hurudishwa.",
  "Is my money at risk?": "Je, pesa zangu ziko hatarini?",
  "Every bot starts on paper with virtual USDC. It can go live once its record earns it. Live trading uses real money and can lose it. Nothing here is financial advice.": "Kila boti huanza kwa majaribio na USDC pepe. Inaweza kwenda moja kwa moja rekodi yake ikistahili. Biashara halisi hutumia pesa halisi na zinaweza kupotea. Hakuna hapa ni ushauri wa kifedha.",
  "The official ARCDEX coin: a fixed supply of 1,000,000,000 with no mint function. Platform fees buy it back and burn it.": "Sarafu rasmi ya ARCDEX: ugavi thabiti wa 1,000,000,000 bila kazi ya kuchapisha. Ada za jukwaa huinunua tena na kuiteketeza.",
