  "The official ARCDEX coin. A fixed supply of 1B with no mint function. Platform fees buy it back and burn it.": "Sarafu rasmi ya ARCDEX. Ugavi thabiti wa bilioni 1 bila kuchapisha. Ada za jukwaa huinunua tena na kuiteketeza.",
