  "Closed paper trades, after every cost. Each strategy can be switched off or tuned on its own (Controls).": "Biashara za majaribio zilizofungwa, baada ya gharama zote. Kila mkakati unaweza kuzimwa au kurekebishwa peke yake (Vidhibiti).",
  "Live results by strategy": "Matokeo ya LIVE kwa mkakati",
  "Live gate": "Lango la LIVE",
  "Live orders need every one of these. Until then the engine trades paper only.": "Oda za LIVE zinahitaji kila moja ya haya. Hadi hapo injini inafanya biashara ya majaribio tu.",
  "Walk-forward validation": "Uthibitisho wa walk-forward",
  "Settings are chosen on a training window, checked on the next one, and judged on a window no choice has seen. The out-of-sample results are what the live gate reads.": "Mipangilio huchaguliwa kwenye kipindi cha mafunzo, hukaguliwa kwenye kinachofuata, na hupimwa kwenye kipindi ambacho hakuna uchaguzi umekiona. Matokeo nje ya sampuli ndiyo lango la LIVE linasoma.",
  "A validation run is going now (a few minutes).": "Uthibitisho unaendelea sasa (dakika chache).",
  "Next run": "Inayofuata",
  "No validation run yet. The first one starts 15 minutes after the engine does.": "Bado hakuna uthibitisho. Wa kwanza unaanza dakika 15 baada ya injini kuanza.",
  "Fold {n}": "Sehemu {n}",
  "{t} trades, {e} a trade": "biashara {t}, {e} kwa biashara",
  "Wallets judged by their closed trades across coins: winning often and by more than they lose, over several coins, and not bots that buy everything. Size alone never makes a wallet smart.": "Pochi hupimwa kwa biashara zao zilizofungwa kwenye coin mbalimbali: hushinda mara nyingi na zaidi ya wanavyopoteza, kwenye coin kadhaa, na si bot zinazonunua kila kitu. Ukubwa pekee haufanyi pochi kuwa janja.",
  "No wallet has a record good enough yet.": "Bado hakuna pochi yenye rekodi nzuri ya kutosha.",
  "Quality": "Ubora",
  "Median": "Wastani wa kati",
  "Realized": "Iliyopatikana",
  "Done.": "Imekamilika.",
  "Owner controls": "Vidhibiti vya mmiliki",
  "Only the engine owner's wallet can use these: each is a message it signs, checked by the engine. Anyone else is refused.": "Pochi ya mmiliki wa injini pekee ndiyo inaweza kutumia hivi: kila kimoja ni ujumbe inaousaini, ukikaguliwa na injini. Mwingine yeyote anakataliwa.",
  "Connect the owner's wallet to sign.": "Unganisha pochi ya mmiliki ili kusaini.",
  "Turn the kill switch off": "Zima swichi ya dharura",
  "Kill switch: stop and sell everything": "Swichi ya dharura: simamisha na uza kila kitu",
  "Run validation now": "Endesha uthibitisho sasa",
  "Change settings": "Badilisha mipangilio",
  "A JSON patch over the settings below, e.g. {\"gates\":{\"minSignalScore\":70}}. Invalid settings are refused; every change is kept as a new version.": "Kiraka cha JSON juu ya mipangilio iliyo hapa chini, mfano {\"gates\":{\"minSignalScore\":70}}. Mipangilio isiyo sahihi inakataliwa; kila badiliko linahifadhiwa kama toleo jipya.",
  "Why (kept with the version)": "Kwa nini (huhifadhiwa pamoja na toleo)",
  "Sign and apply": "Saini na tumia",
  "Current settings": "Mipangilio ya sasa",
  "Every weight, threshold, exit and limit the engine uses (version {v}).": "Kila uzito, kiwango, njia ya kutoka na kikomo injini inachotumia (toleo {v}).",
  "Signal engine": "Injini ya ishara",
  "Autotrade is paused": "Autotrade imesitishwa",
  "Bots don't open new trades for now. Trades already open are still closed as usual, and you can withdraw your USDC at any time.": "Kwa sasa boti hazifungui biashara mpya. Biashara zilizo wazi bado zinafungwa kama kawaida, na unaweza kutoa USDC zako wakati wowote.",
  // ARCDEX landing (2026-10-03)
  "Coins tracked": "Sarafu zinazofuatiliwa",
  "Safety checks a minute": "Ukaguzi wa usalama kwa dakika",
  "BTC, ETH and SOL perpetuals, coming soon.": "Perpetual za BTC, ETH na SOL, zinakuja hivi karibuni.",
  "USDC in, USDC out": "USDC inaingia, USDC inatoka",
  "Margin, profits and fees are all in USDC, the currency Arc runs on.": "Dhamana, faida na ada zote ni kwa USDC, sarafu inayoendesha Arc.",
  "Chainlink prices": "Bei za Chainlink",
  "Positions are priced by Chainlink feeds on Arc, not by thin pools anyone can push.": "Nafasi zinathaminiwa kwa bei za Chainlink kwenye Arc, si kwa mabwawa madogo ambayo mtu yeyote anaweza kusukuma.",
  "Fees fund the pool": "Ada zinajaza bwawa",
  "Fees from $ARCDEX trading are added as liquidity for futures trading.": "Ada kutoka biashara ya $ARCDEX zinaongezwa kama ukwasi kwa biashara ya futures.",
  "A trading app for Arc: a live terminal for every coin, one-tap swaps, a launchpad, a USDC bridge and, soon, perpetual futures.": "Programu ya biashara kwa Arc: terminal hai kwa kila sarafu, kubadilishana kwa mguso mmoja, launchpad, daraja la USDC na, hivi karibuni, perpetual futures.",
  "When do futures launch?": "Futures zitazinduliwa lini?",
  "On Arc testnet first, so traders can try them without risk. Mainnet follows an independent security audit; the date will be announced.": "Kwanza kwenye testnet ya Arc, ili wafanyabiashara wazijaribu bila hatari. Mainnet itafuata baada ya ukaguzi huru wa usalama; tarehe itatangazwa.",
  "What is $ARCDEX?": "$ARCDEX ni nini?",
  "The ARCDEX coin, launched on Argus. Fees from $ARCDEX trading are added as liquidity for futures trading.": "Sarafu ya ARCDEX, iliyozinduliwa kwenye Argus. Ada kutoka biashara ya $ARCDEX zinaongezwa kama ukwasi kwa biashara ya futures.",
  "Yes. Coins on Arc are very volatile, and futures with leverage can lose money quickly. Trade only what you can afford to lose. Nothing here is financial advice.": "Ndiyo. Sarafu kwenye Arc hubadilika bei sana, na futures zenye leverage zinaweza kupoteza pesa haraka. Fanya biashara kwa kiasi unachoweza kumudu kupoteza tu. Hakuna kitu hapa ni ushauri wa kifedha.",
  "Futures": "Futures",
  "Spot and futures trading on Arc.": "Biashara ya spot na futures kwenye Arc.",
  "Trade every coin on Arc in one tap, launch your own, and soon go long or short on BTC, ETH and SOL. All in USDC.": "Fanya biashara ya kila sarafu kwenye Arc kwa mguso mmoja, zindua yako mwenyewe, na hivi karibuni chukua nafasi ya long au short kwenye BTC, ETH na SOL. Yote kwa USDC.",
  "USDC in and out": "USDC kuingia na kutoka",
  "7 languages": "Lugha 7",
  "Long or short": "Long au short",
  "Up to 10× leverage": "Leverage hadi 10×",
  "Testnet first, then mainnet after an independent audit.": "Testnet kwanza, kisha mainnet baada ya ukaguzi huru.",
  "Perpetual futures, coming to Arc": "Perpetual futures, zinakuja kwenye Arc",
  "Long or short BTC, ETH and SOL with up to 10× leverage, settled in USDC and priced by Chainlink. Testnet first, then mainnet after an independent audit.": "Long au short kwenye BTC, ETH na SOL kwa leverage hadi 10×, zikilipwa kwa USDC na kuthaminiwa na Chainlink. Testnet kwanza, kisha mainnet baada ya ukaguzi huru.",
  "Start trading on Arc.": "Anza biashara kwenye Arc.",
  "Create a trading wallet in seconds. No sign-up.": "Unda pochi ya biashara kwa sekunde chache. Bila kujisajili.",
  "Trading crypto is risky, and leveraged futures more so. Nothing here is financial advice.": "Biashara ya crypto ina hatari, na futures zenye leverage zaidi. Hakuna kitu hapa ni ushauri wa kifedha.",
  // ARCDEX: spot and futures first, Autotrade coming soon (2026-10-03)
  "Spot": "Spot",
