  "Trade with free test USDC: nothing here is real money. Mainnet follows an independent audit.": "Fanya biashara kwa USDC za majaribio za bure: hakuna kitu hapa ni pesa halisi. Mainnet itafuata baada ya ukaguzi huru.",
