  "Oracle prices from RedStone, signed every 10 seconds: the prices positions open, close and liquidate at.": "Bei za oracle kutoka RedStone, zilizosainiwa kila sekunde 10: bei ambazo nafasi zinafunguliwa, kufungwa na kufilisiwa.",
