  // Landing: futures on Arc testnet (2026-10-03)
  "BTC, ETH and SOL perpetuals, on Arc testnet.": "Perpetuals za BTC, ETH na SOL, kwenye testnet ya Arc.",
  "Signed oracle prices": "Bei za oracle zilizosainiwa",
  "Positions are priced by RedStone’s signed oracle prices, checked on-chain, not by thin pools anyone can push.": "Nafasi zinapimwa kwa bei za oracle za RedStone zilizosainiwa, zinazokaguliwa kwenye mnyororo, si kwa pool ndogo ambazo yeyote anaweza kuzisukuma.",
  "A spot and perpetual futures exchange on Arc: a live market for every coin, one-tap swaps, a multichain USDC bridge and BTC, ETH and SOL perpetuals, now on Arc testnet.": "Soko la spot na perpetual futures kwenye Arc: soko la moja kwa moja kwa kila sarafu, kubadilisha kwa mguso mmoja, daraja la USDC la minyororo mingi na perpetuals za BTC, ETH na SOL, sasa kwenye testnet ya Arc.",
  "They’re on Arc testnet now: try them with free test USDC, without risk. Mainnet follows an independent security audit; the date will be announced.": "Ziko kwenye testnet ya Arc sasa: zijaribu kwa USDC za majaribio za bure, bila hatari. Mainnet itafuata baada ya ukaguzi huru wa usalama; tarehe itatangazwa.",
  "Trade every coin on Arc in one tap, and go long or short on BTC, ETH and SOL with up to 10× leverage, now on Arc testnet. All in USDC.": "Fanya biashara ya kila sarafu kwenye Arc kwa mguso mmoja, na nenda long au short kwenye BTC, ETH na SOL kwa leverage hadi 10×, sasa kwenye testnet ya Arc. Yote kwa USDC.",
  "On testnet": "Kwenye testnet",
  "Try them on Arc testnet with free test USDC. Mainnet after an independent audit.": "Zijaribu kwenye testnet ya Arc kwa USDC za majaribio za bure. Mainnet baada ya ukaguzi huru.",
  "Perpetual futures on Arc": "Futures za perpetual kwenye Arc",
  "Long or short BTC, ETH and SOL with up to 10× leverage, settled in USDC at RedStone’s signed oracle prices. On Arc testnet now; mainnet after an independent audit.": "Long au short kwenye BTC, ETH na SOL kwa leverage hadi 10×, zikilipwa kwa USDC kwa bei za oracle za RedStone zilizosainiwa. Kwenye testnet ya Arc sasa; mainnet baada ya ukaguzi huru.",
  // $ARCDEX buyback & burn, 30% / 70% (2026-10-03)
  "$ARCDEX burn": "Kuchoma $ARCDEX",
  "$ARCDEX": "$ARCDEX",
  "Fees fund liquidity": "Ada zinafadhili ukwasi",
  "70% of ARCDEX’s fees go to liquidity pools, and 30% buy back $ARCDEX and burn it.": "70% ya ada za ARCDEX zinaenda kwenye pool za ukwasi, na 30% zinanunua tena $ARCDEX na kuziteketeza.",
  "The ARCDEX coin, launched on Argus. 30% of ARCDEX’s fees buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every buyback and burn is on-chain and shown on this page.": "Sarafu ya ARCDEX, iliyozinduliwa kwenye Argus. 30% ya ada za ARCDEX zinanunua tena $ARCDEX na kuziteketeza, na 70% zinaenda kwenye pool za ukwasi. Kila ununuzi na uteketezaji uko kwenye mnyororo na unaonyeshwa kwenye ukurasa huu.",
  "Where the fees go": "Ada zinakoenda",
  "Of the fees ARCDEX collects, 30% buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every number is read from the fee wallet on Arc.": "Kati ya ada ambazo ARCDEX inakusanya, 30% zinanunua tena $ARCDEX na kuziteketeza, na 70% zinaenda kwenye pool za ukwasi. Kila namba inasomwa kutoka pochi ya ada kwenye Arc.",
  "Bought back": "Zilizonunuliwa tena",
