  "$ARCDEX buyback & burn": "Kununua tena na kuteketeza $ARCDEX",
  "Of the fees ARCDEX collects, 30% buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every number below is read from the fee wallet on Arc, so anyone can check it.": "Kati ya ada ambazo ARCDEX inakusanya, 30% zinanunua tena $ARCDEX na kuziteketeza, na 70% zinaenda kwenye pool za ukwasi. Kila namba hapa chini inasomwa kutoka pochi ya ada kwenye Arc, kwa hiyo yeyote anaweza kuikagua.",
  "The ledger can’t be reached right now. Try again in a moment.": "Daftari halipatikani sasa. Jaribu tena baada ya muda mfupi.",
  "since 3 October 2026": "tangu 3 Oktoba 2026",
