  "Add liquidity": "Ongeza ukwasi",
  "to add": "za kuongeza",
  "Add it from this wallet to a pool (or to the futures pool on mainnet); the ledger counts it by itself.": "Uongeze kutoka pochi hii kwenye pool (au pool ya futures kwenye mainnet); daftari linauhesabu lenyewe.",
  "Buybacks, burns and liquidity": "Manunuzi, uteketezaji na ukwasi",
  "Nothing yet: the first buyback and burn will show here.": "Bado hakuna: ununuzi na uteketezaji wa kwanza utaonekana hapa.",
  "Latest fees": "Ada za karibuni",
  "No fees since the program started.": "Hakuna ada tangu mpango uanze.",
  "How it’s counted: fees are USDC that reached the fee wallet from trades and other platform activity. A buyback is a fee-wallet transaction that brought $ARCDEX in; a burn is $ARCDEX it sent to 0x…dEaD; liquidity is value it put into a pool. Burning reduces supply; it doesn’t promise any price.": "Jinsi inavyohesabiwa: ada ni USDC iliyofika kwenye pochi ya ada kutokana na biashara na shughuli nyingine za jukwaa. Kununua tena ni muamala wa pochi ya ada ulioleta $ARCDEX; kuteketeza ni $ARCDEX iliyotumwa kwa 0x…dEaD; ukwasi ni thamani iliyowekwa kwenye pool. Kuteketeza kunapunguza ugavi; hakuahidi bei yoyote.",
