  "Fees shown first": "Ada huonyeshwa kwanza",
  "Circle’s fees and ours are quoted before you sign: what leaves and what arrives.": "Ada za Circle na zetu huonyeshwa kabla ya kusaini: kinachotoka na kinachofika.",
  "Supported networks": "Mitandao inayotumika",
  "Solana can receive USDC from Arc; sending from it needs a Solana wallet.": "Solana inaweza kupokea USDC kutoka Arc; kutuma kutoka Solana kunahitaji pochi ya Solana.",
  "On Arc? Start trading": "Uko kwenye Arc? Anza biashara",
  "USDC on Arc trades every coin on ARCDEX, spot and futures.": "USDC kwenye Arc hufanya biashara ya kila sarafu kwenye ARCDEX, spot na futures.",
  "Swap USDC for any coin on Arc in one tap, and back. USDC on another chain? Bring it over in about a minute.": "Badilisha USDC kwa sarafu yoyote ya Arc kwa mguso mmoja, na kurudi. USDC ziko kwenye mnyororo mwingine? Zilete kwa takriban dakika moja.",
  "Pay with USDC, or sell a coin back to USDC": "Lipa kwa USDC, au uza sarafu kurudi kuwa USDC",
  "Trades go through ARCDEX's swap router (launchpad coins on their bonding curve). Every trade is simulated first, and approvals are for the exact amount only.": "Biashara hupitia router ya ARCDEX (sarafu za launchpad kwenye curve yao). Kila biashara huigwa kwanza, na idhini ni kwa kiasi kamili tu.",
  "USDC on another chain?": "USDC kwenye mnyororo mwingine?",
  "Bring it to Arc from {n} networks with Circle’s CCTP: native USDC, no wrapped tokens, usually under a minute.": "Zilete Arc kutoka mitandao {n} kwa CCTP ya Circle: USDC asilia, hakuna tokeni zilizofungwa, kwa kawaida chini ya dakika moja.",
