  "A Robinhood stock token: it tracks {name}’s share price. Not offered to US persons or in some countries; buying asks where you are first.": "Tokeni ya hisa ya Robinhood: inafuata bei ya hisa ya {name}. Haitolewi kwa raia wa Marekani wala katika baadhi ya nchi; kununua kunauliza kwanza ulipo.",
