  "Arc markets": "Masoko ya Arc",
  "Every launchpad coin on Arc, live, with safety checks.": "Kila sarafu ya launchpad kwenye Arc, moja kwa moja, ikiwa na ukaguzi wa usalama.",
  "Launchpad coins and Robinhood’s stock tokens, bought from Arc.": "Sarafu za launchpad na tokeni za hisa za Robinhood, zinazonunuliwa kutoka Arc.",
  "Buy and sell in one tap, no pop-ups.": "Nunua na uuze kwa mguso mmoja, bila madirisha ibukizi.",
  "USDC from 11 chains.": "USDC kutoka mitandao 11.",
  "Every coin you hold, on every chain, valued live.": "Kila sarafu uliyonayo, kwenye kila mtandao, ikithaminiwa moja kwa moja.",
  "A multichain decentralized exchange: spot trading on Arc and Robinhood Chain, one-tap swaps, a USDC bridge from 11 chains, and BTC, ETH and SOL perpetual futures, now on Arc testnet.": "Soko la ubadilishanaji lisilo na kati kwenye mitandao mingi: biashara ya spot kwenye Arc na Robinhood Chain, swap kwa mguso mmoja, daraja la USDC kutoka mitandao 11, na futures za kudumu za BTC, ETH na SOL, sasa kwenye testnet ya Arc.",
  "ARCDEX’s platform coin, launched on Argus on Arc. 30% of ARCDEX’s fees buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every buyback and burn is on-chain and shown live on this page. Wallets show its symbol as ARCD.": "Sarafu ya jukwaa la ARCDEX, iliyozinduliwa kwenye Argus katika Arc. 30% ya ada za ARCDEX hununua tena $ARCDEX na kuichoma, na 70% huenda kwenye pool za ukwasi. Kila ununuzi tena na uchomaji uko on-chain na unaonyeshwa moja kwa moja kwenye ukurasa huu. Pochi zinaonyesha alama yake kama ARCD.",
  "Which coins can I trade?": "Ni sarafu zipi ninaweza kufanyia biashara?",
  "Only coins launched on a launchpad (on Arc: Argus, Mercuri, SolonPad and others; on Robinhood Chain: Bankr, Pons, Clanker and others) and Robinhood’s own stock tokens. Coins from unknown contracts aren’t listed, because they can be malicious.": "Sarafu zilizozinduliwa kwenye launchpad pekee (kwenye Arc: Argus, Mercuri, SolonPad na zingine; kwenye Robinhood Chain: Bankr, Pons, Clanker na zingine) na tokeni za hisa za Robinhood yenyewe. Sarafu za mikataba isiyojulikana haziorodheshwi, kwa sababu zinaweza kuwa hatari.",
  "Robinhood": "Robinhood",
  "Multichain DEX · live on Arc and Robinhood Chain": "DEX ya mitandao mingi · moja kwa moja kwenye Arc na Robinhood Chain",
  "TRADE ARC & ROBINHOOD.": "FANYA BIASHARA ARC NA ROBINHOOD.",
  "The multichain decentralized exchange for spot and futures: launchpad coins and Robinhood stock tokens, one USDC balance. 30% of every fee buys back $ARCDEX and burns it.": "Soko la ubadilishanaji lisilo na kati la mitandao mingi kwa spot na futures: sarafu za launchpad na tokeni za hisa za Robinhood, salio moja la USDC. 30% ya kila ada hununua tena $ARCDEX na kuichoma.",
  "Of the supply burned": "Ya ugavi imechomwa",
  "$ARCDEX contract on Arc · wallets show the symbol as ARCD": "Mkataba wa $ARCDEX kwenye Arc · pochi zinaonyesha alama ARCD",
  "Two chains. One exchange.": "Mitandao miwili. Soko moja.",
  "Trade Arc and Robinhood Chain from one USDC balance on Arc. Only coins launched on a launchpad are listed, so coins from unknown contracts never reach you.": "Fanya biashara kwenye Arc na Robinhood Chain kwa salio moja la USDC kwenye Arc. Sarafu zilizozinduliwa kwenye launchpad pekee ndizo zinaorodheshwa, kwa hiyo sarafu za mikataba isiyojulikana hazikufikii kamwe.",
  "Every launchpad coin on Arc, live, bonding curves included: one-tap trades with USDC, which is also Arc’s gas.": "Kila sarafu ya launchpad kwenye Arc, moja kwa moja, pamoja na bonding curve: biashara kwa mguso mmoja kwa USDC, ambayo pia ni gesi ya Arc.",
  "more": "zaidi",
  "Launchpad coins and Robinhood’s stock tokens (NVDA, TSLA, SPY…), bought with USDC on Arc and delivered in seconds.": "Sarafu za launchpad na tokeni za hisa za Robinhood (NVDA, TSLA, SPY…), zinazonunuliwa kwa USDC kwenye Arc na kufika ndani ya sekunde.",
  "Robinhood markets": "Masoko ya Robinhood",
  "Launchpad coins only": "Sarafu za launchpad pekee",
  "A coin is listed only if a launchpad launched it, or it’s one of Robinhood’s own stock tokens. Every trade is simulated before it’s sent, and approvals are for the exact amount.": "Sarafu huorodheshwa tu ikiwa launchpad iliizindua, au ni mojawapo ya tokeni za hisa za Robinhood yenyewe. Kila biashara huigwa kabla ya kutumwa, na idhini ni kwa kiasi kamili.",
  "The $ARCDEX burn, live": "Uchomaji wa $ARCDEX, moja kwa moja",
  "Every $ARCDEX sent to the dead address since the coin launched, read from Arc. Burned coins can never move again.": "Kila $ARCDEX iliyotumwa kwenye anwani iliyokufa tangu sarafu ilipozinduliwa, inayosomwa kutoka Arc. Sarafu zilizochomwa haziwezi kusogea tena kamwe.",
