  "Everything to trade, on every chain": "Kila kitu cha kufanya biashara, kwenye kila mtandao",
  "Trade every chain. Hold $ARCDEX.": "Fanya biashara kila mtandao. Shikilia $ARCDEX.",
  "Multichain Decentralized Exchange": "Soko la ubadilishanaji lisilo na kati la mitandao mingi",
  "$ARCDEX is ARCDEX’s platform coin. 30% of ARCDEX’s fees buy it back and burn it, and 70% go to liquidity pools. Every number below is read from Arc, so anyone can check it.": "$ARCDEX ni sarafu ya jukwaa la ARCDEX. 30% ya ada za ARCDEX huinunua tena na kuichoma, na 70% huenda kwenye pool za ukwasi. Kila namba hapa chini inasomwa kutoka Arc, kwa hiyo mtu yeyote anaweza kuikagua.",
