  "Every burn": "Kila uchomaji",
  "Not a launchpad coin: ARCDEX only lists and sells coins launched on a launchpad (and Robinhood’s stock tokens), because coins from unknown contracts can be malicious. You can still sell any you hold.": "Si sarafu ya launchpad: ARCDEX huorodhesha na kuuza sarafu zilizozinduliwa kwenye launchpad pekee (na tokeni za hisa za Robinhood), kwa sababu sarafu za mikataba isiyojulikana zinaweza kuwa hatari. Bado unaweza kuuza ulizonazo.",
  "⚠ This coin wasn’t launched on a launchpad, so ARCDEX doesn’t list it or offer it to buy. Coins from unknown contracts can be malicious.": "⚠ Sarafu hii haikuzinduliwa kwenye launchpad, kwa hiyo ARCDEX haiorodheshi wala kuitoa kwa kununuliwa. Sarafu za mikataba isiyojulikana zinaweza kuwa hatari.",
