  "Hidden by the safety standard: {n} (rated Danger, or under ${usd} of liquidity or {holders} holders).": "Zimefichwa na kiwango cha usalama: {n} (zimepimwa Hatari, au ukwasi chini ya ${usd} au wamiliki chini ya {holders}).",
