  "Safety ratings here come from market data: on-chain checks run on Arc.": "Hapa viwango vya usalama vinatokana na data ya soko: ukaguzi wa on-chain unafanyika kwenye Arc.",
  "The first coin launched with this ticker; the others are duplicates.": "Sarafu ya kwanza kuzinduliwa kwa tika hii; nyingine ni nakala.",
