  "⚠ DUPLICATE · SAME CREATOR": "⚠ NAKALA · MUUNDAJI YULE YULE",
  "duplicates": "nakala",
  "Duplicate": "Nakala",
  "Of the fees ARCDEX collects, 30% buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every number is read from the fee wallet on-chain.": "Kati ya ada ambazo ARCDEX inakusanya, 30% hununua tena $ARCDEX na kuuchoma, na 70% huenda kwenye pool za ukwasi. Kila namba inasomwa on-chain kutoka kwenye pochi ya ada.",
  "Every listed coin, live, with a safety rating.": "Kila sarafu iliyoorodheshwa, moja kwa moja, ikiwa na kiwango cha usalama.",
  "Any listed coin for USDC, in one step.": "Sarafu yoyote iliyoorodheshwa kwa USDC, kwa hatua moja.",
  "Move USDC in and out in about a minute.": "Ingiza na toa USDC kwa takriban dakika moja.",
  "A multichain decentralized exchange: spot trading, one-tap swaps, a USDC bridge, and BTC, ETH and SOL perpetual futures, now on testnet.": "Soko la kubadilishana lisilo la kati la minyororo mingi: biashara ya spot, swap kwa mguso mmoja, daraja la USDC, na futures za kudumu za BTC, ETH na SOL, sasa kwenye testnet.",
  "ARCDEX’s platform coin. 30% of ARCDEX’s fees buy back $ARCDEX and burn it, and 70% go to liquidity pools. Every buyback and burn is on-chain and shown live on this page.": "Sarafu ya jukwaa la ARCDEX. 30% ya ada za ARCDEX hununua tena $ARCDEX na kuuchoma, na 70% huenda kwenye pool za ukwasi. Kila ununuzi na uchomaji uko on-chain na unaonyeshwa moja kwa moja kwenye ukurasa huu.",
  "Open the app, create a trading wallet or connect your own, add USDC, then buy $ARCDEX on its trading page. Always check the contract address: {ca}.": "Fungua programu, unda pochi ya biashara au unganisha yako, ongeza USDC, kisha nunua $ARCDEX kwenye ukurasa wake wa biashara. Hakikisha anwani ya mkataba kila wakati: {ca}.",
  "Coins launched on a launchpad with $15K or more of market cap, and stock tokens. Coins from unknown contracts and coins that have rugged aren’t listed.": "Sarafu zilizozinduliwa kwenye launchpad zenye thamani ya soko ya $15K au zaidi, na tokeni za hisa. Sarafu za mikataba isiyojulikana na sarafu zilizofanyiwa rug hazioorodheshwi.",
  "They’re on testnet now: try them with free test USDC, without risk. Mainnet follows an independent security audit; the date will be announced.": "Ziko kwenye testnet sasa: zijaribu kwa USDC ya majaribio ya bure, bila hatari. Mainnet itafuata baada ya ukaguzi huru wa usalama; tarehe itatangazwa.",
  "Yes. Meme coins are very volatile, and futures with leverage can lose money quickly. Trade only what you can afford to lose. Nothing here is financial advice.": "Ndiyo. Meme coins hubadilika bei sana, na futures zenye leverage zinaweza kupoteza pesa haraka. Fanya biashara kwa kiasi unachoweza kumudu kupoteza tu. Hakuna hapa ni ushauri wa kifedha.",
  "Multichain DEX · spot & futures": "DEX ya minyororo mingi · spot na futures",
  "The multichain decentralized exchange for spot and futures. 30% of every fee buys back $ARCDEX and burns it.": "Soko la kubadilishana lisilo la kati la minyororo mingi kwa spot na futures. 30% ya kila ada hununua tena $ARCDEX na kuuchoma.",
  "Live markets": "Masoko moja kwa moja",
  "No new coin has reached $15K of market cap yet.": "Hakuna sarafu mpya iliyofikia thamani ya soko ya $15K bado.",
  "Long or short BTC, ETH and SOL with up to 10× leverage, settled in USDC at RedStone’s signed oracle prices. On testnet now; mainnet after an independent audit.": "Long au short kwenye BTC, ETH na SOL kwa leverage hadi 10×, hulipwa kwa USDC kwa bei zilizosainiwa za oracle ya RedStone. Kwenye testnet kwa sasa; mainnet baada ya ukaguzi huru.",
  "Everything to trade, in one place": "Kila kitu cha biashara, mahali pamoja",
  "Connecting…": "Inaunganisha…",
  "Arc CA": "CA ya Arc",
  "How far along its launchpad’s curve, as the launchpad counts it": "Imefika wapi kwenye curve ya launchpad yake, kama launchpad inavyohesabu",
  "Selling is signed on Solana and costs a fraction of a cent in SOL: one tap adds some.": "Kuuza kunasainiwa kwenye Solana na hugharimu sehemu ya senti kwa SOL: mguso mmoja unaongeza.",
  "All launchpads": "Launchpad zote",
  "Sort: bonding progress": "Panga: maendeleo ya curve",
  "Loading Solana…": "Inapakia Solana…",
  "Prices and trades from GeckoTerminal; launch curves and mints read from Solana. Coins on Solana are launched by anyone: check a coin before you buy it.": "Bei na biashara kutoka GeckoTerminal; curve za uzinduzi na mint zinasomwa kutoka Solana. Mtu yeyote anaweza kuzindua sarafu kwenye Solana: ikague kabla ya kununua.",
  "Not a launchpad coin: ARCDEX only lists and sells coins launched on a launchpad, because coins from unknown contracts can be malicious. You can still sell any you hold.": "Si sarafu ya launchpad: ARCDEX huorodhesha na kuuza sarafu zilizozinduliwa kwenye launchpad pekee, kwa sababu sarafu za mikataba isiyojulikana zinaweza kuwa hatari. Bado unaweza kuuza ulizonazo.",
  "This coin’s mint can still freeze or inflate it, so ARCDEX doesn’t offer it to buy. You can still sell any you hold.": "Mint ya sarafu hii bado inaweza kuigandisha au kuiongeza, kwa hiyo ARCDEX haiitoi kwa kununua. Bado unaweza kuuza ulizonazo.",
  "Trades on Solana, from GeckoTerminal": "Biashara kwenye Solana, kutoka GeckoTerminal",
  "On {pad}’s bonding curve": "Kwenye bonding curve ya {pad}",
