  "This quote pays {x}× {symbol}’s market price: the route goes through a pool priced far off the market, the way trap pools catch trades. ARCDEX won’t send it.": "Nukuu hii inalipa {x}× bei ya soko ya {symbol}: njia inapita kwenye pool iliyo mbali sana na soko, kama pool za mtego. ARCDEX haitaituma.",
  "The best route loses {n}% of this trade to price impact, so ARCDEX won’t send it. A smaller amount may route better.": "Njia bora inapoteza {n}% ya biashara hii kwa athari ya bei, kwa hiyo ARCDEX haitaituma. Kiasi kidogo kinaweza kupita vizuri zaidi.",
  "Also add ${n} of SOL for fees on Solana, so you can sell later.": "Pia ongeza ${n} za SOL kwa ada kwenye Solana, ili uweze kuuza baadaye.",
  "Selling is signed on Solana, where fees are paid in SOL (a fraction of a cent a sale).": "Kuuza kunasainiwa kwenye Solana, ambapo ada hulipwa kwa SOL (sehemu ya senti kwa kila mauzo).",
  "Add ${n} of SOL": "Ongeza ${n} za SOL",
  "for one-tap trades with no pop-ups. It has a Solana address too.": "kwa biashara ya mguso mmoja bila madirisha ibukizi. Ina anwani ya Solana pia.",
  "Unlock your trading wallet": "Fungua pochi yako ya biashara",
  "Or connect": "Au unganisha",
  "Solana wallet": "Pochi ya Solana",
  "Use {w}": "Tumia {w}",
  "Disconnect": "Tenganisha",
  "Connect {w}": "Unganisha {w}",
  "Solana coins you buy land at this address. It comes from the same key, so your backup covers it.": "Sarafu za Solana unazonunua zinafika kwenye anwani hii. Inatoka kwenye ufunguo ule ule, kwa hiyo nakala yako ya akiba inaihusu.",
  "A contract wallet may not exist at the same address on BNB Chain: buy with an ordinary wallet or the trading wallet.": "Pochi ya mkataba huenda isiwepo kwenye anwani ileile kwenye BNB Chain: nunua kwa pochi ya kawaida au pochi ya biashara.",
  "Add BNB to this wallet from your Arc USDC:": "Ongeza BNB kwenye pochi hii kutoka USDC zako za Arc:",
  "Add a little SOL to this wallet first.": "Kwanza ongeza SOL kidogo kwenye pochi hii.",
  "Adding ${n} of BNB on BNB Chain…": "Inaongeza BNB ya ${n} kwenye BNB Chain…",
  "An unexpected chain to sign on.": "Mnyororo usiotarajiwa wa kusaini.",
  "Approving exactly the amount…": "Inaidhinisha kiasi kamili…",
  "BNB Chain": "BNB Chain",
