  "BNB Chain transaction": "Muamala wa BNB Chain",
  "BNB Chain wallet": "Pochi ya BNB Chain",
  "BNB added on BNB Chain.": "BNB imeongezwa kwenye BNB Chain.",
  "Bought ≈{out} on four.meme’s curve.": "Umenunua ≈{out} kwenye mkunjo wa four.meme.",
  "Bought ≈{out}: it’s in your wallet on BNB Chain.": "Umenunua ≈{out}: iko kwenye pochi yako kwenye BNB Chain.",
  "Coins still on four.meme’s curve: buy and sell with BNB on four.meme’s own contract.": "Sarafu zilizo bado kwenye mkunjo wa four.meme: nunua na uuze kwa BNB kwenye mkataba wa four.meme wenyewe.",
  "Confirm the trade in {wallet}…": "Thibitisha biashara kwenye {wallet}…",
  "Graduated coins trade through Relay with USDC on Arc, BNB or USDT; coins still on four.meme’s curve trade on four.meme’s own contract. Every trade is checked and simulated before it’s sent, and approvals are for the exact amount.": "Sarafu zilizohitimu zinauzwa kupitia Relay kwa USDC za Arc, BNB au USDT; zilizo bado kwenye mkunjo wa four.meme zinauzwa kwenye mkataba wa four.meme wenyewe. Kila biashara inakaguliwa na kuigwa kabla ya kutumwa, na idhini ni za kiasi kamili.",
  "Graduated coins: pay with USDC on Arc, BNB or USDT. The coin lands at your same address on BNB Chain.": "Sarafu zilizohitimu: lipa kwa USDC za Arc, BNB au USDT. Sarafu inafika kwenye anwani yako ileile kwenye BNB Chain.",
  "Launched by four.meme: its contract vouches for this coin": "Imezinduliwa na four.meme: mkataba wake unathibitisha sarafu hii",
  "Loading BNB Chain…": "Inapakia BNB Chain…",
  "No Solana wallet app found in this browser: install Phantom, or use your trading wallet, which has a Solana address too.": "Hakuna programu ya pochi ya Solana kwenye kivinjari hiki: sakinisha Phantom, au tumia pochi yako ya biashara, ambayo pia ina anwani ya Solana.",
  "Not enough BNB for gas on BNB Chain: add BNB first.": "BNB haitoshi kwa gesi kwenye BNB Chain: ongeza BNB kwanza.",
  "Not enough BNB for this trade and its gas.": "BNB haitoshi kwa biashara hii na gesi yake.",
  "Not enough SOL for this trade and its fees.": "SOL haitoshi kwa biashara hii na ada zake.",
  "On BNB Chain": "Kwenye BNB Chain",
  "On four.meme’s curve: traded with BNB.": "Kwenye mkunjo wa four.meme: inauzwa kwa BNB.",
  "On four.meme’s curve: traded with {c}": "Kwenye mkunjo wa four.meme: inauzwa kwa {c}",
  "On its way to BNB Chain…": "Iko njiani kwenda BNB Chain…",
  "Pay with": "Lipa kwa",
  "Pay with SOL": "Lipa kwa SOL",
  "Pay with SOL or USDC from your Solana wallet (Phantom, Solflare…), or with USDC on Arc: the coin lands in your Solana wallet in seconds.": "Lipa kwa SOL au USDC kutoka pochi yako ya Solana (Phantom, Solflare…), au kwa USDC za Arc: sarafu inafika kwenye pochi yako ya Solana kwa sekunde.",
  "Pay with SOL, USDC on Solana or USDC on Arc, and sell for any of them: SOL and Solana USDC through Jupiter, USDC on Arc through Relay. Every trade is checked and simulated before it’s sent, and approvals are for the exact amount.": "Lipa kwa SOL, USDC kwenye Solana au USDC kwenye Arc, na uuze kwa yoyote kati yake: SOL na USDC ya Solana kupitia Jupiter, USDC kwenye Arc kupitia Relay. Kila biashara hukaguliwa na kuigwa kabla ya kutumwa, na idhini ni kwa kiasi kamili.",
  "Pay with SOL, USDC on Solana or USDC on Arc.": "Lipa kwa SOL, USDC za Solana au USDC za Arc.",
  "Pay with USDC on Arc, BNB or USDT.": "Lipa kwa USDC za Arc, BNB au USDT.",
  "Paying with USDC on Arc needs an Arc wallet. Or pay with SOL from your Solana wallet.": "Kulipa kwa USDC za Arc kunahitaji pochi ya Arc. Au lipa kwa SOL kutoka pochi yako ya Solana.",
  "Prices and trades from GeckoTerminal; curves and graduation read from four.meme’s contract on BNB Chain. Coins on four.meme are launched by anyone: check a coin before you buy it.": "Bei na biashara kutoka GeckoTerminal; mikunjo na kuhitimu vinasomwa kutoka mkataba wa four.meme kwenye BNB Chain. Mtu yeyote anaweza kuzindua sarafu kwenye four.meme: kagua sarafu kabla ya kuinunua.",
  "Receive": "Pokea",
  "Relay couldn’t deliver the BNB: your USDC was refunded on Arc.": "Relay haikuweza kuwasilisha BNB: USDC zako zimerudishwa kwenye Arc.",
  "Relay couldn’t fill this trade: it was refunded on BNB Chain.": "Relay haikuweza kukamilisha biashara hii: imerudishwa kwenye BNB Chain.",
  "Relay couldn’t fill this trade: it was refunded on Solana.": "Relay haikuweza kukamilisha biashara hii: imerudishwa kwenye Solana.",
  "Sell any time, for SOL, USDC on Solana or USDC on Arc.": "Uza wakati wowote, kwa SOL, USDC za Solana au USDC za Arc.",
  "Settling…": "Inakamilisha…",
  "Sold for ≈{out}.": "Imeuzwa kwa ≈{out}.",
  "Sold for ≈{out}: it’s in your Solana wallet.": "Imeuzwa kwa ≈{out}: iko kwenye pochi yako ya Solana.",
  "Swap (Relay)": "Ubadilishaji (Relay)",
  "The BNB is still on its way: it lands by itself.": "BNB bado iko njiani: itafika yenyewe.",
  "The price moved past your slippage: check the new quote and try again.": "Bei imepita kiwango chako cha slippage: angalia nukuu mpya ujaribu tena.",
  "This coin trades on four.meme’s older contract: trade it on four.meme.": "Sarafu hii inauzwa kwenye mkataba wa zamani wa four.meme: iuze kwenye four.meme.",
  "This trade would cost more SOL than it should, so ARCDEX won’t send it.": "Biashara hii ingegharimu SOL zaidi ya inavyopaswa, kwa hiyo ARCDEX haitaituma.",
  "Trades on BNB Chain, from GeckoTerminal": "Biashara kwenye BNB Chain, kutoka GeckoTerminal",
  "Trades signed on BNB Chain pay gas in BNB: one tap adds some from your Arc USDC.": "Biashara zinazosainiwa kwenye BNB Chain hulipa gesi kwa BNB: mguso mmoja huongeza kutoka USDC zako za Arc.",
  "Trades signed on BNB Chain pay their gas in BNB (a few cents each).": "Biashara zinazosainiwa kwenye BNB Chain hulipa gesi kwa BNB (senti chache kila moja).",
  "Trades signed on Solana pay their fees in SOL (a fraction of a cent each).": "Biashara zinazosainiwa kwenye Solana hulipa ada kwa SOL (sehemu ya senti kila moja).",
  "You pay ({c})": "Unalipa ({c})",
  "for one-tap trades with no pop-ups: it has the same address on BNB Chain.": "kwa biashara za mguso mmoja bila madirisha ibukizi: ina anwani ileile kwenye BNB Chain.",
  "four.meme fee": "Ada ya four.meme",
  "four.meme has nothing to sell for this amount: the curve may be sold out.": "four.meme haina cha kuuza kwa kiasi hiki: huenda mkunjo umeuzwa wote.",
  "in your Solana wallet in seconds": "kwenye pochi yako ya Solana kwa sekunde",
