  "Not enough gas for this trade on its chain (USDC on Arc, BNB on BNB Chain, ETH on Robinhood Chain): add some first.": "Hakuna gesi ya kutosha kwa biashara hii kwenye mnyororo wake (USDC kwenye Arc, BNB kwenye BNB Chain, ETH kwenye Robinhood Chain): ongeza kwanza.",
  "On its way to {chain}…": "Iko njiani kwenda {chain}…",
  "Open in Phantom": "Fungua kwenye Phantom",
  "Open your ARCDEX account": "Fungua akaunti yako ya ARCDEX",
  "Opened by your Solana wallet’s signature: no passcode, and the same wallet opens it on any device. Pay with SOL or USDC on Solana on any coin page.": "Inafunguliwa kwa sahihi ya wallet yako ya Solana: hakuna nambari ya siri, na wallet hiyo hiyo inaifungua kwenye kifaa chochote. Lipa kwa SOL au USDC kwenye Solana kwenye ukurasa wowote wa sarafu.",
  "Pay with SOL or USDC from your Solana wallet: the coin lands in your ARCDEX account on {chain} in seconds. Sell it back for SOL or USDC any time. Every trade is checked and simulated before it’s sent.": "Lipa kwa SOL au USDC kutoka wallet yako ya Solana: sarafu inafika kwenye akaunti yako ya ARCDEX kwenye {chain} kwa sekunde chache. Iuze tena kwa SOL au USDC wakati wowote. Kila biashara inakaguliwa na kuigwa kabla ya kutumwa.",
  "Pay with SOL or USDC on Solana": "Lipa kwa SOL au USDC kwenye Solana",
  "Phantom, Solflare or Backpack · lands in seconds": "Phantom, Solflare au Backpack · inafika kwa sekunde",
  "Relay couldn’t fill this trade: it was refunded on {chain}.": "Relay haikuweza kukamilisha biashara hii: imerudishwa kwenye {chain}.",
  "SOL or USDC from your Solana wallet (Phantom, Solflare, Backpack), through Relay: USDC on Arc in seconds.": "SOL au USDC kutoka wallet yako ya Solana (Phantom, Solflare, Backpack), kupitia Relay: USDC kwenye Arc kwa sekunde.",
  "SOL or USDC on Solana, here in seconds": "SOL au USDC kwenye Solana, hapa kwa sekunde",
  "SOL or USDC · Relay": "SOL au USDC · Relay",
  "Selling on {chain} needs a little {coin} for gas: buy with SOL once and it’s added, or deposit some.": "Kuuza kwenye {chain} kunahitaji {coin} kidogo kwa gesi: nunua mara moja kwa SOL na itaongezwa, au weka kiasi.",
  "Solana account": "akaunti ya Solana",
  "The wallet’s signature didn’t check out: try again": "Sahihi ya wallet haijathibitika: jaribu tena",
  "This address didn’t fund your account. Your Solana wallet will ask you to confirm it’s you.": "Anwani hii haikuweka pesa kwenye akaunti yako. Wallet yako ya Solana itakuomba uthibitishe ni wewe.",
  "Through Relay: SOL or USDC on Solana in, USDC on Arc out, or back. 0.5% fee. Every transfer is checked and simulated before it’s sent.": "Kupitia Relay: SOL au USDC kwenye Solana inaingia, USDC kwenye Arc inatoka, au kinyume chake. Ada ya 0.5%. Kila uhamisho unakaguliwa na kuigwa kabla ya kutumwa.",
