  "Your ARCDEX account": "Akaunti yako ya ARCDEX",
  "Your ARCDEX account holds what you buy on Arc, BNB Chain and Robinhood Chain. {wallet} signs once to open it; the same wallet opens it on any device.": "Akaunti yako ya ARCDEX inahifadhi unachonunua kwenye Arc, BNB Chain na Robinhood Chain. {wallet} inasaini mara moja kuifungua; wallet hiyo hiyo inaifungua kwenye kifaa chochote.",
  "on {chain} in ~{s}s": "kwenye {chain} ndani ya ~{s}s",
