  "Solana": "Solana",
  "24h volume in our markets": "Kiasi cha saa 24 kwenye masoko yetu",
  "A safety rating on every coin": "Kiwango cha usalama kwa kila sarafu",
  "A screener shows you the chart, then sends you somewhere else to buy. ARCDEX does both, and checks the coin first.": "Screener inakuonyesha chati, kisha inakutuma mahali pengine kununua. ARCDEX inafanya vyote viwili, na inakagua sarafu kwanza.",
  "A sell test, the contract, the creator and the buyers, checked for every coin, with the reasons in words.": "Jaribio la kuuza, mkataba, muundaji na wanunuzi, vinakaguliwa kwa kila sarafu, pamoja na sababu kwa maneno.",
  "A trading wallet in your browser: no sign-up, no pop-ups, no switching apps.": "Wallet ya biashara kwenye kivinjari chako: hakuna usajili, hakuna madirisha ibukizi, hakuna kubadilisha programu.",
  "All markets": "Masoko yote",
  "Buy in one tap": "Nunua kwa mguso mmoja",
  "Coins live now": "Sarafu hai sasa",
  "Find any coin, see whether it’s safe, and buy it in one tap: live markets, a safety rating on every coin, and a wallet that needs no sign-up. Spot and futures.": "Pata sarafu yoyote, ona kama iko salama, na uinunue kwa mguso mmoja: masoko hai, kiwango cha usalama kwa kila sarafu, na wallet isiyohitaji usajili. Spot na futures.",
  "Launchpad coins and established coins with $15K or more of market cap, and stock tokens. Every coin carries a safety rating; coins rated Danger, coins from unknown contracts and coins that have rugged aren’t in the lists.": "Sarafu za launchpad na sarafu imara zenye thamani ya soko ya $15K au zaidi, pamoja na tokeni za hisa. Kila sarafu ina kiwango cha usalama; sarafu zenye Hatari, za mikataba isiyojulikana na zilizofanyiwa rug haziko kwenye orodha.",
  "More than a screener": "Zaidi ya screener",
  "No coin is up today yet.": "Hakuna sarafu iliyopanda leo bado.",
  "Only launchpad coins and established coins with $15K or more of market cap. Coins that rugged drop out.": "Sarafu za launchpad na sarafu imara zenye thamani ya soko ya $15K au zaidi pekee. Sarafu zilizofanyiwa rug zinaondolewa.",
  "Pay from any wallet": "Lipa kutoka wallet yoyote",
  "Pay with SOL or USDC from Phantom, Solflare or Backpack, or USDC from your EVM wallet.": "Lipa kwa SOL au USDC kutoka Phantom, Solflare au Backpack, au USDC kutoka wallet yako ya EVM.",
