  "Your account becomes a unified account, Hyperliquid’s recommended mode: one USDC balance for futures on every market and for predictions.": "Akaunti yako inakuwa akaunti moja (unified), hali inayopendekezwa na Hyperliquid: salio moja la USDC kwa futures katika kila soko na kwa utabiri.",
  "Approve ARCDEX’s fee": "Kubali ada ya ARCDEX",
  "Up to 0.1% of an order’s value, paid to ARCDEX on each trade (0.05% on futures today). You can revoke it at any time on Hyperliquid.": "Hadi 0.1% ya thamani ya oda, inayolipwa ARCDEX kwa kila biashara (0.05% kwenye futures kwa sasa). Unaweza kuiondoa wakati wowote kwenye Hyperliquid.",
  "A trading key for this browser": "Ufunguo wa biashara kwa kivinjari hiki",
  "A key made and kept in this browser places and cancels orders for you, without a pop-up each time. It can never withdraw or move your money.": "Ufunguo uliotengenezwa na kuhifadhiwa kwenye kivinjari hiki unaweka na kufuta oda kwa niaba yako, bila dirisha kila mara. Hauwezi kamwe kutoa wala kuhamisha pesa zako.",
