  "Markets, prices and settlement are Hyperliquid’s: orders are signed in your browser and go straight to it. ARCDEX never holds your money.": "Masoko, bei na malipo ni ya Hyperliquid: oda husainiwa kwenye kivinjari chako na kwenda moja kwa moja huko. ARCDEX haishikilii pesa zako kamwe.",
