  "Checking where you are…": "Inakagua ulipo…",
  "We couldn’t confirm your location, so opening positions is off. Closing positions and withdrawing always work.": "Hatukuweza kuthibitisha ulipo, kwa hiyo kufungua nafasi kumezimwa. Kufunga nafasi na kutoa pesa hufanya kazi kila wakati.",
  "Hyperliquid isn’t available to US persons, Ontario or sanctioned regions. Closing positions and withdrawing always work.": "Hyperliquid haipatikani kwa watu wa Marekani, Ontario wala maeneo yaliyowekewa vikwazo. Kufunga nafasi na kutoa pesa hufanya kazi kila wakati.",
  "Your trading wallet signs each step itself: no pop-ups.": "Pochi yako ya biashara husaini kila hatua yenyewe: bila madirisha.",
  "Your wallet asks you to sign each step once. Nothing is sent on-chain and no gas is paid.": "Pochi yako itakuomba usaini kila hatua mara moja. Hakuna kinachotumwa on-chain wala gesi inayolipwa.",
  "Deposited: your USDC is in your Hyperliquid account.": "Imewekwa: USDC zako ziko kwenye akaunti yako ya Hyperliquid.",
