  "Long or short crypto, stocks, gold, oil and indices with up to 40× leverage, on Hyperliquid’s order books. Orders are signed in your browser; ARCDEX never holds your money.": "Nunua long au uza short kwa crypto, hisa, dhahabu, mafuta na fahirisi kwa leverage hadi 40×, kwenye vitabu vya oda vya Hyperliquid. Oda husainiwa kwenye kivinjari chako; ARCDEX haishikilii pesa zako kamwe.",
