  // Paper trading on Hyperliquid (2026-10-12)
  "Paper trading uses virtual USDC against Hyperliquid’s live prices and order book. Fills, fees (ARCDEX’s included), Hyperliquid’s hourly funding and liquidations are worked out in this browser; the market impact of your own orders and partial fills aren’t. Nothing is sent to Hyperliquid.": "Biashara ya majaribio inatumia USDC ya mtandaoni dhidi ya bei na kitabu cha oda za Hyperliquid kwa wakati halisi. Utekelezaji, ada (pamoja na ya ARCDEX), funding ya kila saa ya Hyperliquid na ufilisi huhesabiwa kwenye kivinjari hiki; athari ya oda zako mwenyewe sokoni na utekelezaji wa sehemu hazihesabiwi. Hakuna kinachotumwa kwa Hyperliquid.",
  "Practise with virtual USDC": "Fanya mazoezi kwa USDC ya mtandaoni",
  "Paper order filled: {sz} {symbol} at {px}": "Oda ya majaribio imetekelezwa: {sz} {symbol} kwa {px}",
