  "Virtual USDC, Hyperliquid’s live prices": "USDC ya mtandaoni, bei halisi za Hyperliquid",
  "Paper positions use isolated margin: a loss stops at the position’s margin.": "Nafasi za majaribio zinatumia margin iliyotenganishwa: hasara inaishia kwenye margin ya nafasi hiyo.",
