  "Check your wallet on testnet": "Kagua pochi yako kwenye testnet",
  "Signs a transfer of 0 STRK to yourself on Starknet Sepolia, then waits for it to be confirmed. Nothing of value moves; the testnet fee is paid in Sepolia STRK.": "Inasaini uhamisho wa STRK 0 kwako mwenyewe kwenye Starknet Sepolia, kisha inasubiri uthibitishwe. Hakuna chenye thamani kinachohamishwa; ada ya testnet hulipwa kwa STRK ya Sepolia.",
  "Waiting for Sepolia…": "Inasubiri Sepolia…",
