  "Before you sign": "Kabla hujasaini",
  "AVNU finds the best route across Starknet’s exchanges and quotes it.": "AVNU hupata njia bora kati ya masoko ya Starknet na kuinukuu.",
  "ARCDEX checks the transaction AVNU builds: an approval of exactly your amount to AVNU’s Exchange, your address as the one paid, and a minimum within your slippage.": "ARCDEX hukagua muamala ambao AVNU huunda: idhini ya kiasi chako hasa kwa Exchange ya AVNU, anwani yako kama inayolipwa, na kiwango cha chini ndani ya slippage yako.",
  "Your wallet signs; the swap settles on Starknet in seconds, and you can follow it on Voyager.": "Pochi yako inasaini; ubadilishaji hukamilika kwenye Starknet kwa sekunde, na unaweza kuufuatilia kwenye Voyager.",
