  // Alchemy and fastest-first RPC (2026-10-12)
  "These are the nodes ARCDEX reads {chain} through: balances, quotes, and the simulation every trade runs before you sign. This browser measures them every 2 minutes and reads through the fastest one that is up to date; a node that throttles or fails steps aside and the next answers. Pin another with Use first.": "Hizi ndizo nodi ambazo ARCDEX husoma {chain} kupitia: salio, bei, na uigaji ambao kila biashara hupitia kabla hujasaini. Kivinjari hiki huzipima kila dakika 2 na husoma kupitia ile yenye kasi zaidi iliyosasishwa; nodi inayopunguza kasi au kushindwa hukaa kando na inayofuata hujibu. Bandika nyingine kwa Tumia kwanza.",
  "ARCDEX’s Alchemy node": "Nodi ya Alchemy ya ARCDEX",
  // Trenches live feed, smart money and the coin bar (2026-10-12)
  "Buy opens Arc’s trade form with this slippage": "Nunua hufungua fomu ya biashara ya Arc na mteremko huu",
  "Wallets with a winning record on this chain, measured by ARCDEX": "Pochi zenye rekodi ya kushinda kwenye mnyororo huu, zilizopimwa na ARCDEX",
  "smart wallets": "pochi janja",
  "Smart": "Janja",
  "Show {lane}": "Onyesha {lane}",
  "A wallet counts as smart after {n}+ closed trades on {chain}, {w}+ of them won, {p}+ in profit, holding over {s}s on average (bots that flip in seconds don’t count). Measured from the trades ARCDEX has seen since {since}.": "Pochi huhesabiwa janja baada ya biashara {n}+ zilizofungwa kwenye {chain}, {w}+ zikiwa za ushindi, faida ya {p}+, ikishikilia zaidi ya sekunde {s} kwa wastani (roboti zinazouza kwa sekunde hazihesabiwi). Imepimwa kutoka biashara ambazo ARCDEX imeona tangu {since}.",
  "{n} wallets": "pochi {n}",
  "Buying now": "Wananunua sasa",
  "Minimize": "Punguza",
  "Connecting to the live feed…": "Inaunganisha na mtiririko wa moja kwa moja…",
  "Learning which wallets win on {chain}": "Inajifunza pochi zinazoshinda kwenye {chain}",
  "{n} wallets followed since {since}. None has a winning record yet.": "Pochi {n} zinafuatiliwa tangu {since}. Hakuna yenye rekodi ya kushinda bado.",
  "No smart wallet has bought in the last {m} minutes.": "Hakuna pochi janja iliyonunua katika dakika {m} zilizopita.",
  "No smart wallet has traded yet since you opened this page.": "Hakuna pochi janja iliyofanya biashara tangu ufungue ukurasa huu.",
  "This wallet: {n} closed trades, {w} won, {p} realized": "Pochi hii: biashara {n} zilizofungwa, {w} za ushindi, {p} zilizopatikana",
  "Smart = a winning record on {chain}, measured by ARCDEX from on-chain trades. Not advice.": "Janja = rekodi ya kushinda kwenye {chain}, iliyopimwa na ARCDEX kutoka biashara za mnyororoni. Si ushauri.",
