  "Every venue": "Kila soko",
  "Write a reason first (3 characters or more): it goes in the audit log and on the banner.": "Andika sababu kwanza (herufi 3 au zaidi): inaingia kwenye kumbukumbu ya ukaguzi na kwenye bango.",
  "Trading is back on: {where}.": "Biashara imerudi: {where}.",
  "Trading is off: {where}. New trades there are refused before signing.": "Biashara imezimwa: {where}. Biashara mpya huko hukataliwa kabla ya kusainiwa.",
  "Trade switch": "Swichi ya biashara",
  "Turn trading off everywhere or on one venue. New trades there are refused before anything is signed; withdrawals, transfers and the bridge keep working, and Hyperliquid positions can still be closed. Only an admin wallet can change it, and every change is kept in the audit log.": "Zima biashara kila mahali au kwenye soko moja. Biashara mpya huko hukataliwa kabla ya kusaini chochote; kutoa pesa, kutuma na daraja vinaendelea kufanya kazi, na nafasi za Hyperliquid bado zinaweza kufungwa. Ni pochi ya msimamizi tu inayoweza kuibadilisha, na kila badiliko huhifadhiwa kwenye kumbukumbu ya ukaguzi.",
  "The engine isn’t configured on this build, so the switch can’t be read.": "Injini haijawekwa kwenye toleo hili, kwa hiyo swichi haiwezi kusomwa.",
  "Reading…": "Inasoma…",
  "Trading is on everywhere": "Biashara iko wazi kila mahali",
