  "Fee {pct}, $0.05 to $50 (90% to the fee wallet, 10% to Circle)": "Ada {pct}, $0.05 hadi $50 (90% kwa pochi ya ada, 10% kwa Circle)",
  "1% a trade and 40% of creator tax, fixed in the contract; $3 a launch": "1% kwa kila biashara na 40% ya kodi ya muundaji, zimewekwa kwenye mkataba; $3 kwa kila uzinduzi",
  "Fee wallet (VITE_FEE_RECIPIENT_EVM)": "Pochi ya ada (VITE_FEE_RECIPIENT_EVM)",
