  "The fee must be between 0 and {max} basis points.": "Ada lazima iwe kati ya 0 na pointi za msingi {max}.",
  "Only the router’s owner ({owner}) can change its fee.": "Ni mmiliki wa ruta ({owner}) tu anayeweza kubadilisha ada yake.",
  "The transaction reverted on-chain.": "Muamala ulirudishwa on-chain.",
  "Set on-chain": "Imewekwa on-chain",
  "Over the daily limit of {limit}: send it in parts, or back to the wallet that funded this one.": "Zaidi ya kikomo cha kila siku cha {limit}: tuma kwa sehemu, au rudisha kwenye pochi iliyoweka pesa kwenye hii.",
  "Daily limit: {left} left until {time}. Sending back to the wallet that funded this one has no limit.": "Kikomo cha kila siku: zimebaki {left} hadi {time}. Kurudisha kwenye pochi iliyoweka pesa kwenye hii hakuna kikomo.",
  "This address is new: {left} can go now, the full amount from {time}.": "Anwani hii ni mpya: {left} zinaweza kutumwa sasa, kiasi chote kuanzia {time}.",
  "This address is new: {left} can go now. Save it to send the full amount 24 hours from now.": "Anwani hii ni mpya: {left} zinaweza kutumwa sasa. Ihifadhi ili kutuma kiasi chote baada ya saa 24.",
  "Enter an Arc address: 0x and 40 letters or numbers.": "Weka anwani ya Arc: 0x na herufi au namba 40.",
  "That’s the zero address: anything sent there is lost.": "Hiyo ni anwani sifuri: chochote kinachotumwa huko hupotea.",
  "That’s this wallet’s own address.": "Hiyo ni anwani ya pochi hii yenyewe.",
  "That’s a token’s contract, not a wallet: anything sent there is lost.": "Hiyo ni mkataba wa tokeni, si pochi: chochote kinachotumwa huko hupotea.",
  "{what} sent to {to}": "{what} zimetumwa kwa {to}",
  "From your ARCDEX trading wallet. If this wasn’t you, move the rest of your funds back to the wallet that funded it now.": "Kutoka kwenye pochi yako ya biashara ya ARCDEX. Kama si wewe, rudisha sasa pesa zako zilizobaki kwenye pochi iliyoiwekea pesa.",
  "New withdrawal address saved: {to}": "Anwani mpya ya kutoa imehifadhiwa: {to}",
  "It can take the full amount from {time}. If this wasn’t you, move your funds back to the wallet that funded this one now.": "Inaweza kupokea kiasi chote kuanzia {time}. Kama si wewe, rudisha sasa pesa zako kwenye pochi iliyoweka pesa kwenye hii.",
  "Checking your withdraw limits… try again in a moment.": "Inakagua vikomo vyako vya kutoa… jaribu tena baada ya muda mfupi.",
