  "This address is a contract. Exchanges and smart wallets can be; make sure it takes USDC on Arc.": "Anwani hii ni mkataba. Masoko ya kubadilishana na pochi janja zinaweza kuwa hivyo; hakikisha inapokea USDC kwenye Arc.",
  "Transfers on Arc can’t be reversed. Check the address matches the one you meant, character by character at the ends.": "Uhamisho kwenye Arc hauwezi kurudishwa. Hakikisha anwani ndiyo uliyokusudia, herufi kwa herufi mwanzoni na mwishoni.",
