  "This trade would take more than the amount shown, so ARCDEX won’t send it.": "Biashara hii ingechukua zaidi ya kiasi kilichoonyeshwa, kwa hiyo ARCDEX haitaituma.",
  "This trade would deliver less than its minimum, so ARCDEX won’t send it.": "Biashara hii ingeleta chini ya kiwango chake cha chini, kwa hiyo ARCDEX haitaituma.",
