  "Jupiter (Relay while Jupiter isn’t on)": "Jupiter (Relay wakati Jupiter haijawashwa)",
  "A swap on Solana alone, signed by your Solana wallet. Through Jupiter, ARCDEX’s fee is paid in the same transaction.": "Swap kwenye Solana pekee, iliyosainiwa na pochi yako ya Solana. Kupitia Jupiter, ada ya ARCDEX hulipwa kwenye muamala huo huo.",
