  "Not on: set VITE_JUP_REFERRAL_ACCOUNT and JUPITER_API_KEY on Netlify (Relay trades them meanwhile)": "Haijawashwa: weka VITE_JUP_REFERRAL_ACCOUNT na JUPITER_API_KEY kwenye Netlify (Relay inaziendesha kwa sasa)",
  "Fee ledger": "Daftari la ada",
