  "Admin": "Msimamizi",
  "Sign in with an admin wallet to see who’s online, fees, trades and the audit log, and to change flags or run the fee sweeper. Every change asks for your wallet’s signature again and is kept in the audit log. The kill switch and the routers’ fee work without signing in.": "Ingia kwa pochi ya msimamizi ili kuona walio mtandaoni, ada, biashara na kumbukumbu ya ukaguzi, na kubadilisha bendera au kuendesha kifagia ada. Kila badiliko huomba tena saini ya pochi yako na huhifadhiwa kwenye kumbukumbu ya ukaguzi. Swichi ya dharura na ada ya ruta hufanya kazi bila kuingia.",
