  "Run the sweep for real? Fees bots owe are sent to the fee wallet; the rest is reported for you to claim.": "Endesha ufagiaji kwa kweli? Ada wanazodaiwa boti hutumwa kwenye pochi ya ada; zilizobaki unaarifiwa ili uzidai.",
  "Sweep ({mode}): {status}. Sent {sent}; for you to claim {owner}.": "Ufagiaji ({mode}): {status}. Imetumwa {sent}; unazodai {owner}.",
  "dry run": "jaribio",
  "for real": "kwa kweli",
  "Fee sweeper": "Kifagia ada",
  "Fees are paid to the fee wallet inside each trade. The sweeper finds what still sits elsewhere: fees bots owe (sent to the fee wallet), and fees held at Relay or in Jupiter’s referral account (for you to claim with that wallet). It runs every day; a second run the same day does nothing.": "Ada hulipwa kwenye pochi ya ada ndani ya kila biashara. Kifagia hupata kilichobaki mahali pengine: ada wanazodaiwa boti (hutumwa kwenye pochi ya ada), na ada zinazoshikiliwa na Relay au kwenye akaunti ya rufaa ya Jupiter (uzidai kwa pochi hiyo). Huendeshwa kila siku; mara ya pili siku hiyo hiyo haifanyi chochote.",
  "Nothing is held outside the fee wallet.": "Hakuna kinachoshikiliwa nje ya pochi ya ada.",
  "under the threshold": "chini ya kiwango",
  "the sweeper sends it": "kifagia hukituma",
