  "From the fee ledger: the trades index (Supabase) isn’t readable from the engine, so each row is a fee received.": "Kutoka daftari la ada: faharasa ya biashara (Supabase) haisomeki kutoka injini, kwa hiyo kila mstari ni ada iliyopokelewa.",
