  "Every admin action, kept for good: the table refuses changes and deletions.": "Kila kitendo cha msimamizi, huhifadhiwa milele: jedwali hukataa mabadiliko na ufutaji.",
  "the engine": "injini",
  "Write a reason first (3 characters or more): it goes in the audit log.": "Andika sababu kwanza (herufi 3 au zaidi): inaingia kwenye kumbukumbu ya ukaguzi.",
  "{flag} is now {state}. Open pages pick it up within 5 minutes.": "{flag} sasa iko {state}. Kurasa zilizo wazi huichukua ndani ya dakika 5.",
  "Turn a feature on or off for everyone without a deploy. A flag set on Netlify (VITE_FLAG_…) still wins, and protections can only be turned on here: turning one off takes a deploy.": "Washa au zima kipengele kwa kila mtu bila kusambaza upya. Bendera iliyowekwa kwenye Netlify (VITE_FLAG_…) bado ina nguvu zaidi, na kinga zinaweza kuwashwa tu hapa: kuzima moja kunahitaji kusambaza upya.",
