  "Not rated here": "Haijakadiriwa hapa",
  "Open the coin’s page to see its safety rating before buying.": "Fungua ukurasa wa sarafu kuona ukadiriaji wake wa usalama kabla ya kununua.",
  "I understand this coin is rated Danger and I could lose everything I put in.": "Ninaelewa kwamba sarafu hii imekadiriwa Hatari na ninaweza kupoteza kila kitu ninachoweka.",
  "Referral rebate": "Rejesho la rufaa",
  "paid to the referrer": "limelipwa kwa mrejeleaji",
  "Referral rebates too: each one against the router’s event, the transfer that paid it, the share of the fee, and the referrer the router holds for that trader.": "Marejesho ya rufaa pia: kila moja dhidi ya tukio la router, uhamisho ulioilipa, sehemu ya ada, na mrejeleaji ambaye router inamhifadhi kwa mfanyabiashara huyo.",
  "Referral rebates": "Marejesho ya rufaa",
