  "trader": "mfanyabiashara",
  "It uses a Robinhood stock name, but Robinhood didn’t issue it": "Inatumia jina la hisa ya Robinhood, lakini Robinhood haikuitoa",
  "{sym} is on AVNU’s verified token list: the only Starknet tokens ARCDEX offers": "{sym} iko kwenye orodha ya tokeni zilizothibitishwa za AVNU: tokeni pekee za Starknet ambazo ARCDEX inatoa",
  "Alerts on this device need ARCDEX’s market engine, which this build doesn’t reach.": "Arifa kwenye kifaa hiki zinahitaji injini ya soko ya ARCDEX, ambayo toleo hili haliifikii.",
  "Alerts on this device are switched off for now.": "Arifa kwenye kifaa hiki zimezimwa kwa sasa.",
  "This browser can’t receive alerts with ARCDEX closed. On an iPhone, add ARCDEX to your home screen first.": "Kivinjari hiki hakiwezi kupokea arifa ARCDEX ikiwa imefungwa. Kwenye iPhone, ongeza ARCDEX kwenye skrini ya mwanzo kwanza.",
  "🔔 Alerts reach this device": "🔔 Arifa zinafika kwenye kifaa hiki",
  "Get alerts with ARCDEX closed": "Pata arifa ARCDEX ikiwa imefungwa",
  "Checked by ARCDEX’s engine around the clock, sent within seconds.": "Zinakaguliwa na injini ya ARCDEX saa zote, zinatumwa ndani ya sekunde.",
  "A notification on this device, even with every ARCDEX tab closed.": "Arifa kwenye kifaa hiki, hata vichupo vyote vya ARCDEX vikiwa vimefungwa.",
