  "last {time}": "mwisho {time}",
  "ARCDEX’s engine checks every trade on this coin and sends the alert to this device within seconds. A price alert fires once; a whale alert at most once a minute.": "Injini ya ARCDEX inakagua kila biashara ya sarafu hii na kutuma arifa kwenye kifaa hiki ndani ya sekunde. Arifa ya bei inalia mara moja; arifa ya nyangumi isizidi mara moja kwa dakika.",
  "email sign-in": "kuingia kwa barua pepe",
  "Export keys": "Hamisha funguo",
  "Email & social sign-in (Privy)": "Kuingia kwa barua pepe au mitandao ya kijamii (Privy)",
  "Privy confirms it": "Privy inathibitisha",
  "Email or social account": "Akaunti ya barua pepe au mitandao ya kijamii",
  "No wallet app: an EVM and a Solana wallet are made for you": "Bila programu ya pochi: pochi ya EVM na ya Solana zinaundwa kwa ajili yako",
  "For your safety, sign in again before sending to this address.": "Kwa usalama wako, ingia tena kabla ya kutuma kwa anwani hii.",
  "Sign in again": "Ingia tena",
  "This address isn’t one of your own. Privy will ask for your two-step verification code before it sends.": "Anwani hii si yako. Privy itakuuliza msimbo wako wa uthibitishaji wa hatua mbili kabla ya kutuma.",
  "This address isn’t one of your own. For your safety, sign in again (email code or social account) before sending to it. With two-step verification on (Manage account), Privy asks for a code instead.": "Anwani hii si yako. Kwa usalama wako, ingia tena (msimbo wa barua pepe au akaunti ya kijamii) kabla ya kutuma kwake. Uthibitishaji wa hatua mbili ukiwa umewashwa (Simamia akaunti), Privy huuliza msimbo badala yake.",
  "To export a key, sign in again first (or turn on two-step verification).": "Ili kuhamisha ufunguo, ingia tena kwanza (au washa uthibitishaji wa hatua mbili).",
  "Email & social sign-in": "Kuingia kwa barua pepe au mitandao ya kijamii",
  "Signed in as {who}. Privy made an EVM and a Solana wallet for this account; Privy confirms every transaction in its own window.": "Umeingia kama {who}. Privy imeunda pochi ya EVM na ya Solana kwa akaunti hii; Privy huthibitisha kila muamala katika dirisha lake.",
  "your account": "akaunti yako",
  "EVM wallet": "Pochi ya EVM",
  "Same address on Arc, Ethereum, Arbitrum, BNB Chain and Robinhood Chain": "Anwani ileile kwenye Arc, Ethereum, Arbitrum, BNB Chain na Robinhood Chain",
  "Being made…": "Inaundwa…",
  "Two-step verification": "Uthibitishaji wa hatua mbili",
  "Privy asks for a code before keys or money leave the account. Recommended.": "Privy huuliza msimbo kabla funguo au pesa hazijatoka kwenye akaunti. Inapendekezwa.",
  "Manage": "Simamia",
  "Privy shows the key in its own window: ARCDEX never sees it. Anyone with the key controls the wallet.": "Privy huonyesha ufunguo katika dirisha lake: ARCDEX haiuoni kamwe. Yeyote mwenye ufunguo anadhibiti pochi.",
  "EVM key": "Ufunguo wa EVM",
