  "Email sign-in couldn’t be reached. Try again, or use another wallet.": "Kuingia kwa barua pepe hakupatikani. Jaribu tena, au tumia pochi nyingine.",
  "Sign in to ARCDEX": "Ingia kwenye ARCDEX",
  "With your email or a social account. Your EVM and Solana wallets are made for you.": "Kwa barua pepe yako au akaunti ya kijamii. Pochi zako za EVM na Solana zinaundwa kwa ajili yako.",
