  "Realized PnL recomputed from ARCDEX’s router trades on Arc (average cost per coin), read from the chain to block {block}.": "Faida/hasara iliyopatikana imekokotolewa upya kutoka kwa biashara za ruta za ARCDEX kwenye Arc (gharama ya wastani kwa sarafu), imesomwa kwenye mnyororo hadi bloku {block}.",
  "1 wallet left out by the wash-trade filter": "Pochi 1 imeachwa nje na kichujio cha biashara bandia",
