  "More about this trader": "Zaidi kuhusu mfanyabiashara huyu",
  "You muted this wallet: its theses and comments are hidden for you.": "Umenyamazisha pochi hii: tasnifu na maoni yake yamefichwa kwako.",
  "Unmute": "Acha kunyamazisha",
  "Recomputed from {n} trades through ARCDEX’s routers on Arc, read from the chain to block {block}. Average cost per coin; tokens sold without a cost here don’t count.": "Imekokotolewa upya kutoka kwa biashara {n} kupitia ruta za ARCDEX kwenye Arc, zilizosomwa kwenye mnyororo hadi bloku {block}. Gharama ya wastani kwa sarafu; sarafu zilizouzwa bila gharama hapa hazihesabiwi.",
  "Left out of the leaderboards": "Imeachwa nje ya majedwali ya washindi",
  "{n} round trips in 30 days, {pct}% of its volume: coins bought and sold straight back for about the same.": "Mara {n} za kununua na kuuza papo hapo ndani ya siku 30, {pct}% ya kiasi chake: sarafu zilizonunuliwa na kuuzwa mara moja kwa karibu bei ileile.",
