  "Enough people reported it: it’s hidden until the ARCDEX team looks at it.": "Watu wa kutosha wameiripoti: imefichwa hadi timu ya ARCDEX iiangalie.",
  "The ARCDEX team reviews reports. It’s hidden once several people report it.": "Timu ya ARCDEX hukagua ripoti. Hufichwa watu kadhaa wakiiripoti.",
