  "Wallet tracker": "Kifuatiliaji cha pochi",
  "Follow any wallet on Arc, Robinhood Chain, Solana or BNB Chain and see its buys and sells the moment they happen.": "Fuatilia pochi yoyote kwenye Arc, Robinhood Chain, Solana au BNB Chain na uone manunuzi na mauzo yake papo hapo.",
