  "No wallets yet. Paste an address above, or start with one of the smart wallets below.": "Bado hakuna pochi. Bandika anwani hapo juu, au anza na moja ya pochi smart hapa chini.",
  "Smart wallets on {chain}": "Pochi smart kwenye {chain}",
  "No trades yet. New ones show here the moment they happen; on Solana, Robinhood Chain and BNB Chain, trades are kept from when you start following.": "Bado hakuna biashara. Mpya zinaonekana hapa papo hapo; kwenye Solana, Robinhood Chain na BNB Chain, biashara huhifadhiwa tangu unapoanza kufuatilia.",
  "Follow a wallet to see its trades here.": "Fuatilia pochi ili kuona biashara zake hapa.",
