  "You can copy up to {n} leaders.": "Unaweza kunakili hadi viongozi {n}.",
  "Followed": "Inafuatiliwa",
  "Pick traders to copy. Your own trading wallet makes the same trades on Arc within seconds, under your rules. Your money never leaves your wallet.": "Chagua wafanyabiashara wa kunakili. Pochi yako ya biashara hufanya biashara zilezile kwenye Arc ndani ya sekunde, kwa sheria zako. Pesa zako haziondoki kwenye pochi yako.",
  "Copy trading is switched off for now.": "Copy trading imezimwa kwa sasa.",
  "From your trading wallet {w} · {cash} USDC": "Kutoka kwenye pochi yako ya biashara {w} · USDC {cash}",
  "Copy trading uses your built-in trading wallet, which signs without pop-ups.": "Copy trading hutumia pochi yako ya biashara iliyojengwa ndani, inayosaini bila madirisha ibukizi.",
  "Open the trading wallet": "Fungua pochi ya biashara",
  "Daily budget ($)": "Bajeti ya siku ($)",
  "Spent today: {n}": "Iliyotumika leo: {n}",
  "Copies happen only while ARCDEX is open in a tab on this device.": "Nakala hufanyika tu wakati ARCDEX iko wazi kwenye kichupo kwenye kifaa hiki.",
  "Copying copies losses as faithfully as gains. Meme coins can lose most or all of their value in minutes.": "Kunakili hunakili hasara kwa uaminifu uleule kama faida. Meme coins zinaweza kupoteza karibu thamani yote ndani ya dakika.",
  "Copies are made after the leader trades, at a different price, and some are skipped (your rules, the safety check, the budget, a price that moved).": "Nakala hufanywa baada ya kiongozi kufanya biashara, kwa bei tofauti, na baadhi hurukwa (sheria zako, ukaguzi wa usalama, bajeti, bei iliyobadilika).",
  "Your trading wallet signs every copy by itself, without asking you each time, while copying is on.": "Pochi yako ya biashara husaini kila nakala yenyewe, bila kukuuliza kila mara, wakati kunakili kumewashwa.",
  "Only Arc trades in Uniswap pools are copied for now, not coins still on a launchpad’s curve. Every copy pays ARCDEX’s normal fee and gas.": "Kwa sasa ni biashara za Arc kwenye pools za Uniswap pekee zinazonakiliwa, si sarafu ambazo bado ziko kwenye curve ya launchpad. Kila nakala hulipa ada ya kawaida ya ARCDEX na gas.",
  "I understand, and only use money I can afford to lose.": "Ninaelewa, na ninatumia pesa tu ninazoweza kumudu kupoteza.",
