  "every one-minute candle, one typed decision per market: regime, direction, toxic flow, setup quality 0–3 and a calibrated confidence.": "kila mshumaa wa dakika moja, uamuzi mmoja wenye muundo kwa kila soko: hali ya soko, mwelekeo, mtiririko hatari, ubora wa mpangilio 0–3 na uhakika uliosawazishwa.",
  "Gates": "Vizuizi",
  "it trades only when quality is at least {q}, confidence is above {c}% and the risk state is safe, with a positive expectation after fees.": "hufanya biashara tu ubora ukiwa angalau {q}, uhakika ukizidi {c}% na hali ya hatari ikiwa salama, na matarajio chanya baada ya ada.",
  "a quarter of the Kelly fraction, never more than {r}% of equity at risk, at most {l}× leverage.": "robo ya sehemu ya Kelly, kamwe si zaidi ya {r}% ya mtaji hatarini, mkopo usiozidi {l}×.",
  "Brain": "Ubongo",
  "Claude re-reads a position when the reflex loses confidence, and reviews every day. It can only hold or close.": "Claude husoma upya nafasi reflex inapopoteza uhakika, na hufanya tathmini kila siku. Anaweza tu kushikilia au kufunga.",
  "not connected: the code closes a position when the reflex loses confidence.": "haujaunganishwa: msimbo hufunga nafasi reflex inapopoteza uhakika.",
  "Limits": "Vikomo",
  "a {d}% drawdown trips the kill switch and closes everything; a {l}% daily loss stops new trades until tomorrow.": "kushuka kwa {d}% huwasha swichi ya kusimamisha na kufunga kila kitu; hasara ya {l}% kwa siku huzuia biashara mpya hadi kesho.",
  "Decisions": "Maamuzi",
  "Every candle, every market. Most say no: that is the point.": "Kila mshumaa, kila soko. Mengi husema hapana: ndiyo lengo.",
