  "No trades yet. It trades only when a setup clears every gate.": "Bado hakuna biashara. Hufanya biashara tu mpangilio unapopita vizuizi vyote.",
  "When it says 80%, does it happen 80% of the time? Fit on older decisions, scored on the last day it never saw.": "Akisema 80%, je hutokea mara 80%? Imesawazishwa kwa maamuzi ya zamani, imepimwa kwenye siku iliyopita ambayo haijawahi kuiona.",
