  "Replay": "Marudio",
  "The same agent run over the stored candles when it started, to calibrate it. A measurement, not a promise.": "Wakala yuleyule, akiendeshwa kwenye mishumaa iliyohifadhiwa alipoanza, ili kumsawazisha. Kipimo, si ahadi.",
