  "Max drawdown": "Kushuka kwa juu kabisa",
  "Nightly reviews": "Tathmini za usiku",
  "Each day: the fills and misses, the calibration, and changes it proposes. A change ships only if a replay shows it does better; gates and limits never change by themselves.": "Kila siku: biashara zilizofanyika na zilizokosekana, usawazishaji, na mabadiliko anayopendekeza. Badiliko hutumika tu marudio yakionyesha ni bora zaidi; vizuizi na vikomo havibadiliki vyenyewe.",
  "The first review runs after its first full day.": "Tathmini ya kwanza hufanyika baada ya siku yake kamili ya kwanza.",
  "Agent wallet on Arc testnet": "Pochi ya wakala kwenye Arc testnet",
  "{u} tUSDC, {g} USDC for gas": "{u} tUSDC, {g} USDC kwa gesi",
  "Futures carry risk. ARCDEX Algo trades test USDC; its results are measured, not promised, and past results say little about the future.": "Futures zina hatari. ARCDEX Algo hufanya biashara kwa USDC ya majaribio; matokeo yake hupimwa, hayaahidiwi, na matokeo ya zamani hayasemi mengi kuhusu siku zijazo.",
  "Why it closed": "Kwa nini ilifungwa",
