  "Trades checked on their chains: {ok} counted, {p} waiting, {f} failed or not from that wallet, {u} not checkable.": "Biashara zilizokaguliwa kwenye minyororo yake: {ok} zimehesabiwa, {p} zinasubiri, {f} zimeshindwa au si za pochi hiyo, {u} hazikaguliki.",
  "Latest trades from the site": "Biashara za karibuni kutoka kwenye tovuti",
  "Users are wallets used on the site. A trade counts once its transaction is found on its chain, sent by that wallet; ARCDEX’s Arc router trades are read from the chain directly. Fees are the fee ledger’s, read on-chain.": "Watumiaji ni pochi zilizotumika kwenye tovuti. Biashara inahesabiwa muamala wake ukipatikana kwenye mnyororo wake, ukitumwa na pochi hiyo; biashara za ruta ya Arc ya ARCDEX zinasomwa moja kwa moja kwenye mnyororo. Ada ni za daftari la ada, zilizosomwa on-chain.",
  "Log in with your email, add USDC, then buy $ARCDEX on its trading page. Always check the contract address: {ca}.": "Ingia kwa barua pepe yako, ongeza USDC, kisha nunua $ARCDEX kwenye ukurasa wake wa biashara. Hakikisha anwani ya mkataba kila mara: {ca}.",
  "Find any coin, see whether it’s safe, and buy it in one tap: live markets on four chains, a safety rating on every coin, futures and predictions. Log in with your email or Google: your wallet is made for you.": "Pata sarafu yoyote, ona kama iko salama, na uinunue kwa mguso mmoja: masoko hai kwenye minyororo minne, ukadiriaji wa usalama kwa kila sarafu, futures na utabiri. Ingia kwa barua pepe au Google: pochi yako inatengenezwa kwa ajili yako.",
  "Log in and start trading": "Ingia uanze kufanya biashara",
