  "Log in with your email or Google and your wallet is made for you: no app to install, no seed phrase to write down.": "Ingia kwa barua pepe au Google na pochi yako inatengenezwa kwa ajili yako: hakuna programu ya kusakinisha, hakuna maneno ya siri ya kuandika.",
  "Log in with your email: your wallet is ready in seconds.": "Ingia kwa barua pepe yako: pochi yako iko tayari kwa sekunde chache.",
